--liquibase formatted sql

--changeset nexadrop:v133-documentos-legales-en-bd splitStatements:false
--
-- Los cinco documentos legales pasan a la base para que el admin pueda editarlos.
--
-- Vivían como constantes de TypeScript dentro del escaparate: cambiar una coma exigía tocar código,
-- compilar y desplegar, y quien tiene que revisar un texto legal no es quien despliega. Aquí quedan
-- editables, versionados y con el mismo contenido que había publicado — la semilla sale de volcar el
-- módulo real, no de copiarlo a mano, así que las interpolaciones (${CO.name}, ${CO.email}) llegan ya
-- resueltas y no como marcadores sin sustituir.
--
-- El cuerpo se guarda como JSON con la misma forma que consume el escaparate ({intro, sections}): así el
-- editor del admin y la página pública comparten estructura y no hay que traducir de un formato a otro.
--
-- `published` distingue el borrador de lo publicado: el admin puede guardar a medias sin que el
-- escaparate lo enseñe. Y la versión viaja en la fila porque es lo que se guarda como constancia de lo
-- que cada usuario aceptó.
--
CREATE TABLE IF NOT EXISTS legal_document (
    id           uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    doc_type     varchar(20)  NOT NULL,
    lang         varchar(5)   NOT NULL,
    title        varchar(200) NOT NULL,
    body         jsonb        NOT NULL,
    version      varchar(20)  NOT NULL,
    published    boolean      NOT NULL DEFAULT true,
    updated_by   varchar(120),
    created_at   timestamptz  NOT NULL DEFAULT now(),
    updated_at   timestamptz  NOT NULL DEFAULT now(),
    CONSTRAINT uk_legal_document UNIQUE (doc_type, lang)
);

CREATE INDEX IF NOT EXISTS idx_legal_document_lookup ON legal_document (doc_type, lang) WHERE published;

COMMENT ON TABLE  legal_document IS 'Textos legales editables desde el admin. Sustituyen a las constantes del escaparate.';
COMMENT ON COLUMN legal_document.body IS 'JSON {intro, sections:[{h, p:[...]}]} — misma forma que consume la página pública.';

INSERT INTO legal_document (doc_type, lang, title, body, version) VALUES
('privacy','es','Política de privacidad','{"intro": "Qué datos tuyos tratamos, para qué, con quién los compartimos y qué puedes exigirnos. Está escrita para poder comprobarse: si algo de aquí no se corresponde con lo que hacemos, es un error nuestro y queremos saberlo.", "sections": [{"h": "Quién trata tus datos", "p": ["Responsable: Jesús Enrique Finol Finol, con NIF PENDIENTE-NIF y domicilio en Calle Castelví 7, 1D, 50004 Zaragoza, España, que opera bajo el nombre comercial NX036. Para cualquier cuestión sobre privacidad o para ejercer tus derechos, escribe a support@nx036.com."]}, {"h": "Qué datos recogemos", "p": ["De tu cuenta: nombre y apellidos, email, teléfono, empresa (si la indicas), país e idioma. De tus pedidos: dirección de envío y facturación, contenido del pedido e historial de pagos. De lo que publicas: las reseñas que escribes, con tu nombre visible y tu país. Del uso: dirección IP, país deducido de ella, dispositivo y páginas visitadas. No pedimos ni queremos datos de categorías especiales (salud, ideología, biometría)."]}, {"h": "Para qué y con qué base legal", "p": ["Para crear y gestionar tu cuenta, procesar y enviar tus pedidos, cobrarlos y atenderte: ejecución del contrato. Para cumplir con la facturación y la fiscalidad: obligación legal. Para prevenir el fraude y mantener la seguridad: interés legítimo. Para cookies no esenciales y comunicaciones comerciales: tu consentimiento, que puedes retirar cuando quieras."]}, {"h": "Con quién los compartimos", "p": ["Con los proveedores que hacen falta para prestarte el servicio, cada uno como encargado del tratamiento y sólo con lo imprescindible: pasarelas de pago (Stripe, PayPal), transporte y aduanas, correo electrónico e infraestructura. No vendemos tus datos ni los cedemos para publicidad de terceros."]}, {"h": "Tus datos salen de la Unión Europea", "p": ["Los pedidos se envían desde China. Para que tu paquete llegue, el transportista necesita —y recibe— tu nombre, dirección completa, código postal, teléfono y email. Es una transferencia internacional a un país sin decisión de adecuación, amparada en que es necesaria para ejecutar el contrato de compraventa que tú mismo has solicitado (art. 49.1.b del RGPD) y respaldada por cláusulas contractuales tipo con el transportista. Sin esa transferencia no hay forma de entregarte el pedido."]}, {"h": "Cuánto tiempo los guardamos", "p": ["Los datos de tu cuenta, mientras la mantengas abierta. Las facturas y los datos fiscales, los plazos que marca la ley española (seis años), aunque cierres la cuenta: es una obligación que no podemos saltarnos. Los registros técnicos de seguridad, 12 meses. Cuando borras tu cuenta, todo lo demás se elimina o se anonimiza de forma irreversible."]}, {"h": "Qué puedes exigirnos", "p": ["Acceder a tus datos, rectificarlos, suprimirlos, oponerte al tratamiento, pedir que se limite y llevártelos a otro servicio (portabilidad). También retirar cualquier consentimiento que hayas dado, sin que eso afecte a lo hecho antes.", "Desde tu perfil puedes descargarte una copia completa de tus datos en formato JSON y eliminar tu cuenta tú mismo, sin pedir permiso a nadie. Para el resto, escribe a support@nx036.com: te responderemos en un mes.", "Si crees que no hemos hecho bien nuestro trabajo, puedes reclamar ante la Agencia Española de Protección de Datos (www.aepd.es), que es nuestra autoridad de control, o ante la del país donde resides. Puedes elegir la que te resulte más cómoda."]}, {"h": "Cookies", "p": ["Usamos cookies técnicas necesarias para que la web funcione y, sólo si lo consientes, cookies de analítica y marketing. Puedes cambiar o retirar tu decisión cuando quieras desde el enlace del pie de página. El detalle, cookie por cookie, está en la política de cookies."]}, {"h": "Decisiones automatizadas", "p": ["No tomamos decisiones automatizadas que produzcan efectos jurídicos sobre ti ni te afecten significativamente. No hacemos elaboración de perfiles con esa finalidad."]}, {"h": "Menores", "p": ["La plataforma no está dirigida a menores de 14 años y no creamos cuentas a sabiendas para ellos. Si detectamos una, la eliminamos."]}]}','2026-08-15'),
('privacy','en','Privacy policy','{"intro": "What data of yours we process, what for, who we share it with, and what you can demand from us. It is written to be checked: if anything here does not match what we do, that is our mistake and we want to hear about it.", "sections": [{"h": "Who processes your data", "p": ["Controller: Jesús Enrique Finol Finol, tax ID PENDIENTE-NIF, address Calle Castelví 7, 1D, 50004 Zaragoza, España, trading as NX036. For any privacy matter or to exercise your rights, write to support@nx036.com."]}, {"h": "What we collect", "p": ["From your account: name and surname, email, phone, company (if given), country and language. From your orders: shipping and billing address, order contents and payment history. From what you publish: the reviews you write, with your display name and country. From usage: IP address, device and pages visited. We do not ask for and do not want special category data (health, beliefs, biometrics)."]}, {"h": "Why, and on what legal basis", "p": ["To create and manage your account, process and ship your orders, charge for them and support you: performance of the contract. To comply with invoicing and tax law: legal obligation. To prevent fraud and keep the service secure: legitimate interest. For non-essential cookies and marketing messages: your consent, which you can withdraw at any time."]}, {"h": "Who we share it with", "p": ["With the providers needed to serve you, each as a processor and only with what is strictly necessary: payment gateways (Stripe, PayPal), shipping and customs, email and infrastructure. We do not sell your data or hand it over for third-party advertising."]}, {"h": "Your data leaves the European Union", "p": ["Orders ship from China. For your parcel to arrive, the carrier needs — and receives — your name, full address, postcode, phone and email. This is an international transfer to a country without an adequacy decision, relying on it being necessary to perform the sales contract you yourself requested (GDPR art. 49.1.b) and backed by standard contractual clauses with the carrier. Without that transfer there is no way to deliver your order."]}, {"h": "How long we keep it", "p": ["Your account data, for as long as you keep the account open. Invoices and tax records, for the periods Spanish law requires (six years), even if you close your account: that is an obligation we cannot waive. Technical security logs, 12 months. When you delete your account, everything else is erased or irreversibly anonymised."]}, {"h": "What you can demand from us", "p": ["Access your data, correct it, erase it, object to processing, ask for it to be restricted, and take it to another service (portability). Also withdraw any consent you gave, without affecting what was done before.", "From your profile you can download a full copy of your data as JSON and delete your account yourself, without asking anyone. For anything else, write to support@nx036.com: we answer within one month.", "If you think we have not done our job properly, you may complain to the Spanish Data Protection Agency (www.aepd.es), our supervisory authority, or to the authority of the country where you live. Whichever is easier for you."]}, {"h": "Cookies", "p": ["We use technical cookies needed for the site to work and, only if you consent, analytics and marketing cookies. You can change or withdraw your decision at any time from the footer link. The detail, cookie by cookie, is in the cookie policy."]}, {"h": "Automated decisions", "p": ["We make no automated decisions producing legal effects on you or significantly affecting you. We do no profiling for that purpose."]}, {"h": "Minors", "p": ["The platform is not aimed at children under 14 and we do not knowingly create accounts for them. If we find one, we delete it."]}]}','2026-08-15'),
('privacy','pt','Política de privacidade','{"intro": "Que dados seus tratamos, para quê, com quem os partilhamos e o que nos pode exigir. Está escrita para poder ser verificada: se algo aqui não corresponder ao que fazemos, é um erro nosso e queremos saber.", "sections": [{"h": "Quem trata os seus dados", "p": ["Responsável: Jesús Enrique Finol Finol, NIF PENDIENTE-NIF, com domicílio em Calle Castelví 7, 1D, 50004 Zaragoza, España, que opera sob o nome comercial NX036. Para qualquer questão de privacidade ou para exercer os seus direitos, escreva para support@nx036.com."]}, {"h": "Que dados recolhemos", "p": ["Da sua conta: nome e apelidos, email, telefone, empresa (se indicar), país e idioma. Das suas encomendas: morada de envio e faturação, conteúdo da encomenda e histórico de pagamentos. Do que publica: as avaliações que escreve, com o seu nome visível e o seu país. Do que publica: as avaliações que escreve, com o seu nome visível e o seu país. Da utilização: endereço IP, país deduzido, dispositivo e páginas visitadas. Não pedimos nem queremos dados de categorias especiais (saúde, convicções, biometria)."]}, {"h": "Para quê e com que base legal", "p": ["Para criar e gerir a sua conta, processar e enviar encomendas, cobrá-las e atendê-lo: execução do contrato. Para cumprir a faturação e a fiscalidade: obrigação legal. Para prevenir fraude e manter a segurança: interesse legítimo. Para cookies não essenciais e comunicações comerciais: o seu consentimento, que pode retirar quando quiser."]}, {"h": "Com quem os partilhamos", "p": ["Com os fornecedores necessários para lhe prestar o serviço, cada um como subcontratante e apenas com o indispensável: gateways de pagamento (Stripe, PayPal), transporte e alfândega, email e infraestrutura. Não vendemos os seus dados nem os cedemos para publicidade de terceiros."]}, {"h": "Os seus dados saem da União Europeia", "p": ["As encomendas são enviadas da China. Para a sua encomenda chegar, a transportadora precisa — e recebe — do seu nome, morada completa, código postal, telefone e email. É uma transferência internacional para um país sem decisão de adequação, fundada em ser necessária para executar o contrato de compra e venda que o próprio solicitou (art. 49.º, n.º 1, alínea b) do RGPD) e apoiada em cláusulas contratuais-tipo com a transportadora. Sem essa transferência não há forma de lhe entregar a encomenda."]}, {"h": "Durante quanto tempo os guardamos", "p": ["Os dados da conta, enquanto a mantiver aberta. As faturas e dados fiscais, pelos prazos da lei espanhola (seis anos), mesmo que encerre a conta: é uma obrigação que não podemos dispensar. Os registos técnicos de segurança, 12 meses. Quando apaga a conta, todo o resto é eliminado ou anonimizado de forma irreversível."]}, {"h": "O que nos pode exigir", "p": ["Aceder aos seus dados, retificá-los, apagá-los, opor-se ao tratamento, pedir a sua limitação e levá-los para outro serviço (portabilidade). Também retirar qualquer consentimento dado, sem afetar o que foi feito antes.", "A partir do seu perfil pode descarregar uma cópia completa dos seus dados em JSON e eliminar a conta por si próprio, sem pedir autorização a ninguém. Para o resto, escreva para support@nx036.com: respondemos no prazo de um mês.", "Se considerar que não fizemos bem o nosso trabalho, pode reclamar junto da Agência Espanhola de Proteção de Dados (www.aepd.es), a nossa autoridade de controlo, ou da autoridade do país onde reside. A que lhe for mais cómoda."]}, {"h": "Cookies", "p": ["Usamos cookies técnicas necessárias ao funcionamento e, apenas se consentir, cookies de analítica e marketing. Pode alterar ou retirar a sua decisão quando quiser a partir da ligação no rodapé. O detalhe, cookie a cookie, está na política de cookies."]}, {"h": "Decisões automatizadas", "p": ["Não tomamos decisões automatizadas com efeitos jurídicos sobre si nem que o afetem significativamente. Não fazemos definição de perfis com essa finalidade."]}, {"h": "Menores", "p": ["A plataforma não se dirige a menores de 14 anos e não criamos contas para eles conscientemente. Se detetarmos alguma, eliminamo-la."]}]}','2026-08-15'),
('privacy','zh','隐私政策','{"intro": "我们处理您哪些数据、用于什么目的、与谁共享,以及您可以向我们主张什么。本政策写得可供核查:如有任何内容与我们的实际做法不符,那是我们的错误,请告知我们。", "sections": [{"h": "谁在处理您的数据", "p": ["控制者:Jesús Enrique Finol Finol,税号 PENDIENTE-NIF,地址 Calle Castelví 7, 1D, 50004 Zaragoza, España,商号 NX036。任何隐私问题或行使权利,请发送邮件至 support@nx036.com。"]}, {"h": "我们收集哪些数据", "p": ["账户信息:姓名、邮箱、电话、公司(如填写)、国家/地区与语言。订单信息:收货与账单地址、订单内容与支付记录。您发布的内容:您撰写的评价,含显示名称与国家/地区。使用信息:IP 地址、设备与访问页面。我们不索取也不需要特殊类别数据(健康、信仰、生物识别)。"]}, {"h": "目的与法律依据", "p": ["创建和管理账户、处理与发运订单、收款及提供支持:履行合同。遵守开票与税务规定:法定义务。防范欺诈与保障安全:合法利益。非必要 Cookie 与营销信息:您的同意,可随时撤回。"]}, {"h": "与谁共享", "p": ["仅与为您提供服务所必需的供应商共享,各自作为受托处理者且仅限必要范围:支付网关(Stripe、PayPal)、运输与海关、电子邮件与基础设施。我们不出售您的数据,也不将其提供给第三方用于广告。"]}, {"h": "您的数据会离开欧盟", "p": ["订单从中国发出。为使包裹送达,承运人需要并会收到您的姓名、完整地址、邮编、电话与邮箱。这属于向无充分性认定国家的国际传输,依据是履行您本人请求的买卖合同所必需(GDPR 第 49 条第 1 款 b 项),并以与承运人签订的标准合同条款作为保障。没有该传输就无法为您送货。"]}, {"h": "保存多久", "p": ["账户数据在您保持账户开通期间保存。发票与税务记录按西班牙法律要求的期限保存(六年),即使您注销账户亦然:这是我们无法免除的义务。技术安全日志保存 12 个月。您删除账户后,其余数据将被删除或不可逆匿名化。"]}, {"h": "您可以向我们主张什么", "p": ["访问、更正、删除您的数据,反对处理,请求限制处理,以及将数据携带至其他服务(可携带权)。也可以撤回已作出的任何同意,且不影响此前已进行的处理。", "在个人中心,您可以自行下载 JSON 格式的完整数据副本并删除账户,无需任何人批准。其他事项请发送邮件至 support@nx036.com:我们将在一个月内答复。", "若您认为我们未妥善履职,可向作为我们监管机构的西班牙数据保护局(www.aepd.es)投诉,也可向您居住国的监管机构投诉,以方便者为准。"]}, {"h": "Cookies", "p": ["我们使用网站运行所必需的技术性 Cookie;仅在您同意时,使用分析与营销 Cookie。您可随时通过页脚链接更改或撤回决定。逐项明细见 Cookie 政策。"]}, {"h": "自动化决策", "p": ["我们不作出对您产生法律效果或重大影响的自动化决策,也不为此进行用户画像。"]}, {"h": "未成年人", "p": ["本平台不面向 14 岁以下未成年人,我们不会明知而为其创建账户。一经发现,即予删除。"]}]}','2026-08-15'),
('privacy','fr','Politique de confidentialité','{"intro": "Quelles données vous concernant nous traitons, pourquoi, avec qui nous les partageons et ce que vous pouvez exiger de nous. Elle est écrite pour être vérifiée : si quelque chose ici ne correspond pas à ce que nous faisons, c’est notre erreur et nous voulons le savoir.", "sections": [{"h": "Qui traite vos données", "p": ["Responsable : Jesús Enrique Finol Finol, n° fiscal PENDIENTE-NIF, domicilié à Calle Castelví 7, 1D, 50004 Zaragoza, España, exerçant sous le nom commercial NX036. Pour toute question de confidentialité ou pour exercer vos droits, écrivez à support@nx036.com."]}, {"h": "Ce que nous collectons", "p": ["De votre compte : nom et prénom, e-mail, téléphone, société (le cas échéant), pays et langue. De vos commandes : adresse de livraison et de facturation, contenu de la commande et historique des paiements. De ce que vous publiez : les avis que vous rédigez, avec votre nom affiché et votre pays. De l’usage : adresse IP, appareil et pages visitées. Nous ne demandons ni ne souhaitons de données sensibles (santé, convictions, biométrie)."]}, {"h": "Pourquoi, et sur quelle base légale", "p": ["Créer et gérer votre compte, traiter et expédier vos commandes, les encaisser et vous assister : exécution du contrat. Respecter la facturation et la fiscalité : obligation légale. Prévenir la fraude et assurer la sécurité : intérêt légitime. Cookies non essentiels et messages commerciaux : votre consentement, retirable à tout moment."]}, {"h": "Avec qui nous les partageons", "p": ["Avec les prestataires nécessaires au service, chacun comme sous-traitant et uniquement avec le strict nécessaire : passerelles de paiement (Stripe, PayPal), transport et douane, e-mail et infrastructure. Nous ne vendons pas vos données et ne les cédons pas à des fins publicitaires tierces."]}, {"h": "Vos données quittent l’Union européenne", "p": ["Les commandes sont expédiées depuis la Chine. Pour que votre colis arrive, le transporteur a besoin — et reçoit — de vos nom, adresse complète, code postal, téléphone et e-mail. Il s’agit d’un transfert international vers un pays sans décision d’adéquation, fondé sur sa nécessité pour exécuter le contrat de vente que vous avez vous-même demandé (art. 49.1.b du RGPD) et encadré par des clauses contractuelles types avec le transporteur. Sans ce transfert, aucune livraison n’est possible."]}, {"h": "Combien de temps nous les conservons", "p": ["Les données de votre compte, tant qu’il reste ouvert. Les factures et données fiscales, pendant les délais prévus par la loi espagnole (six ans), même si vous fermez le compte : c’est une obligation à laquelle nous ne pouvons déroger. Les journaux techniques de sécurité, 12 mois. À la suppression de votre compte, tout le reste est effacé ou anonymisé de façon irréversible."]}, {"h": "Ce que vous pouvez exiger", "p": ["Accéder à vos données, les rectifier, les effacer, vous opposer au traitement, en demander la limitation et les emporter vers un autre service (portabilité). Ainsi que retirer tout consentement donné, sans effet sur ce qui a précédé.", "Depuis votre profil, vous pouvez télécharger une copie complète de vos données en JSON et supprimer votre compte vous-même, sans autorisation de personne. Pour le reste, écrivez à support@nx036.com : nous répondons sous un mois.", "Si vous estimez que nous avons mal fait notre travail, vous pouvez saisir l’Agence espagnole de protection des données (www.aepd.es), notre autorité de contrôle, ou celle du pays où vous résidez — en France, la CNIL. Celle qui vous arrange le plus."]}, {"h": "Cookies", "p": ["Nous utilisons des cookies techniques nécessaires au fonctionnement et, seulement avec votre consentement, des cookies d’analyse et de marketing. Vous pouvez modifier ou retirer votre décision à tout moment depuis le lien en pied de page. Le détail, cookie par cookie, figure dans la politique de cookies."]}, {"h": "Décisions automatisées", "p": ["Nous ne prenons aucune décision automatisée produisant des effets juridiques vous concernant ou vous affectant de manière significative. Aucun profilage à cette fin."]}, {"h": "Mineurs", "p": ["La plateforme ne s’adresse pas aux moins de 14 ans et nous ne créons pas sciemment de comptes pour eux. Si nous en détectons un, nous le supprimons."]}]}','2026-08-15'),
('privacy','de','Datenschutzerklärung','{"intro": "Welche deiner Daten wir verarbeiten, wozu, mit wem wir sie teilen und was du von uns verlangen kannst. Sie ist so geschrieben, dass man sie überprüfen kann: Wenn hier etwas nicht dem entspricht, was wir tun, ist das unser Fehler und wir wollen davon erfahren.", "sections": [{"h": "Wer deine Daten verarbeitet", "p": ["Verantwortlicher: Jesús Enrique Finol Finol, Steuernummer PENDIENTE-NIF, Anschrift Calle Castelví 7, 1D, 50004 Zaragoza, España, tätig unter dem Handelsnamen NX036. Bei Datenschutzfragen oder zur Ausübung deiner Rechte schreibe an support@nx036.com."]}, {"h": "Welche Daten wir erheben", "p": ["Aus deinem Konto: Vor- und Nachname, E-Mail, Telefon, Firma (falls angegeben), Land und Sprache. Aus deinen Bestellungen: Liefer- und Rechnungsadresse, Bestellinhalt und Zahlungshistorie. Aus dem, was du veröffentlichst: deine Bewertungen mit Anzeigename und Land. Aus der Nutzung: IP-Adresse, Gerät und besuchte Seiten. Besondere Datenkategorien (Gesundheit, Überzeugungen, Biometrie) fragen wir nicht ab und wollen wir nicht."]}, {"h": "Wozu und auf welcher Rechtsgrundlage", "p": ["Konto anlegen und verwalten, Bestellungen abwickeln und versenden, abrechnen und dich betreuen: Vertragserfüllung. Rechnungsstellung und Steuerrecht: rechtliche Verpflichtung. Betrugsprävention und Sicherheit: berechtigtes Interesse. Nicht notwendige Cookies und Werbenachrichten: deine Einwilligung, jederzeit widerrufbar."]}, {"h": "Mit wem wir sie teilen", "p": ["Mit den für den Service nötigen Dienstleistern, jeweils als Auftragsverarbeiter und nur mit dem Notwendigsten: Zahlungsdienste (Stripe, PayPal), Versand und Zoll, E-Mail und Infrastruktur. Wir verkaufen deine Daten nicht und geben sie nicht für Fremdwerbung weiter."]}, {"h": "Deine Daten verlassen die Europäische Union", "p": ["Bestellungen werden aus China versandt. Damit dein Paket ankommt, benötigt und erhält der Transporteur deinen Namen, die vollständige Adresse, Postleitzahl, Telefonnummer und E-Mail. Das ist eine Übermittlung in ein Land ohne Angemessenheitsbeschluss, gestützt darauf, dass sie zur Erfüllung des von dir selbst gewünschten Kaufvertrags erforderlich ist (Art. 49 Abs. 1 lit. b DSGVO), abgesichert durch Standardvertragsklauseln mit dem Transporteur. Ohne diese Übermittlung ist keine Zustellung möglich."]}, {"h": "Wie lange wir sie speichern", "p": ["Kontodaten, solange du das Konto offen hältst. Rechnungen und Steuerdaten für die gesetzlichen Fristen nach spanischem Recht (sechs Jahre), auch wenn du das Konto schließt: eine Pflicht, von der wir nicht abweichen können. Technische Sicherheitsprotokolle 12 Monate. Beim Löschen deines Kontos wird alles Übrige gelöscht oder unwiderruflich anonymisiert."]}, {"h": "Was du von uns verlangen kannst", "p": ["Auskunft, Berichtigung, Löschung, Widerspruch gegen die Verarbeitung, Einschränkung und Mitnahme zu einem anderen Dienst (Datenübertragbarkeit). Ebenso den Widerruf jeder erteilten Einwilligung, ohne dass das Vorherige berührt wird.", "In deinem Profil kannst du eine vollständige Kopie deiner Daten als JSON herunterladen und dein Konto selbst löschen, ohne jemanden zu fragen. Für alles Weitere schreibe an support@nx036.com: Wir antworten innerhalb eines Monats.", "Wenn du meinst, wir hätten unsere Arbeit nicht gut gemacht, kannst du dich bei der spanischen Datenschutzbehörde AEPD (www.aepd.es) — unserer Aufsichtsbehörde — oder bei der Aufsichtsbehörde deines Wohnsitzlandes beschweren. Ganz wie es dir leichter fällt."]}, {"h": "Cookies", "p": ["Wir verwenden technisch notwendige Cookies und, nur mit deiner Einwilligung, Analyse- und Marketing-Cookies. Du kannst deine Entscheidung jederzeit über den Link im Fußbereich ändern oder widerrufen. Die Einzelheiten, Cookie für Cookie, stehen in der Cookie-Richtlinie."]}, {"h": "Automatisierte Entscheidungen", "p": ["Wir treffen keine automatisierten Entscheidungen mit rechtlicher Wirkung oder erheblicher Beeinträchtigung für dich. Kein Profiling zu diesem Zweck."]}, {"h": "Minderjährige", "p": ["Die Plattform richtet sich nicht an Personen unter 14 Jahren, und wir legen für sie wissentlich keine Konten an. Entdecken wir eines, löschen wir es."]}]}','2026-08-15'),
('privacy','it','Informativa sulla privacy','{"intro": "Quali tuoi dati trattiamo, per quale finalità, con chi li condividiamo e cosa puoi pretendere da noi. È scritta per poter essere verificata: se qualcosa qui non corrisponde a ciò che facciamo, è un nostro errore e vogliamo saperlo.", "sections": [{"h": "Chi tratta i tuoi dati", "p": ["Titolare: Jesús Enrique Finol Finol, codice fiscale PENDIENTE-NIF, con domicilio in Calle Castelví 7, 1D, 50004 Zaragoza, España, che opera con il nome commerciale NX036. Per qualsiasi questione sulla privacy o per esercitare i tuoi diritti scrivi a support@nx036.com."]}, {"h": "Quali dati raccogliamo", "p": ["Dal tuo account: nome e cognome, email, telefono, azienda (se indicata), Paese e lingua. Dai tuoi ordini: indirizzo di spedizione e fatturazione, contenuto dell’ordine e storico dei pagamenti. Da ciò che pubblichi: le recensioni che scrivi, con il tuo nome visibile e il tuo Paese. Dall’utilizzo: indirizzo IP, dispositivo e pagine visitate. Non chiediamo né vogliamo dati particolari (salute, convinzioni, biometria)."]}, {"h": "Perché e con quale base giuridica", "p": ["Per creare e gestire il tuo account, elaborare e spedire gli ordini, incassarli e assisterti: esecuzione del contratto. Per adempiere agli obblighi di fatturazione e fiscali: obbligo di legge. Per prevenire frodi e garantire la sicurezza: legittimo interesse. Per i cookie non essenziali e le comunicazioni commerciali: il tuo consenso, revocabile in qualsiasi momento."]}, {"h": "Con chi li condividiamo", "p": ["Con i fornitori necessari a erogare il servizio, ciascuno come responsabile del trattamento e solo con lo stretto indispensabile: gateway di pagamento (Stripe, PayPal), trasporto e dogana, email e infrastruttura. Non vendiamo i tuoi dati né li cediamo per pubblicità di terzi."]}, {"h": "I tuoi dati escono dall’Unione Europea", "p": ["Gli ordini partono dalla Cina. Perché il pacco arrivi, il vettore ha bisogno — e riceve — di nome, indirizzo completo, CAP, telefono ed email. È un trasferimento internazionale verso un Paese privo di decisione di adeguatezza, fondato sulla necessità di eseguire il contratto di vendita che hai richiesto tu stesso (art. 49.1.b del GDPR) e sostenuto da clausole contrattuali tipo con il vettore. Senza quel trasferimento non c’è modo di consegnarti l’ordine."]}, {"h": "Per quanto tempo li conserviamo", "p": ["I dati dell’account finché lo mantieni aperto. Le fatture e i dati fiscali per i termini previsti dalla legge spagnola (sei anni), anche se chiudi l’account: è un obbligo a cui non possiamo sottrarci. I log tecnici di sicurezza, 12 mesi. Quando elimini l’account, tutto il resto viene cancellato o anonimizzato in modo irreversibile."]}, {"h": "Cosa puoi pretendere da noi", "p": ["Accedere ai tuoi dati, rettificarli, cancellarli, opporti al trattamento, chiederne la limitazione e portarli a un altro servizio (portabilità). Nonché revocare qualsiasi consenso prestato, senza pregiudizio per quanto già svolto.", "Dal tuo profilo puoi scaricare una copia completa dei tuoi dati in JSON ed eliminare l’account da solo, senza chiedere il permesso a nessuno. Per il resto scrivi a support@nx036.com: rispondiamo entro un mese.", "Se ritieni che non abbiamo svolto bene il nostro lavoro, puoi rivolgerti all’Agenzia spagnola per la protezione dei dati (www.aepd.es), la nostra autorità di controllo, o all’autorità di controllo del Paese in cui risiedi. Quella che ti è più comoda."]}, {"h": "Cookie", "p": ["Usiamo cookie tecnici necessari al funzionamento e, solo con il tuo consenso, cookie di analisi e marketing. Puoi modificare o revocare la tua decisione quando vuoi dal link nel piè di pagina. Il dettaglio, cookie per cookie, è nella cookie policy."]}, {"h": "Decisioni automatizzate", "p": ["Non adottiamo decisioni automatizzate che producano effetti giuridici o che ti riguardino in modo significativo. Nessuna profilazione a tale scopo."]}, {"h": "Minori", "p": ["La piattaforma non si rivolge a minori di 14 anni e non creiamo consapevolmente account per loro. Se ne rileviamo uno, lo eliminiamo."]}]}','2026-08-15'),
('privacy','nl','Privacybeleid','{"intro": "Welke gegevens van jou we verwerken, waarvoor, met wie we ze delen en wat je van ons kunt eisen. Het is geschreven om gecontroleerd te worden: klopt iets hier niet met wat we doen, dan is dat onze fout en willen we het horen.", "sections": [{"h": "Wie je gegevens verwerkt", "p": ["Verwerkingsverantwoordelijke: Jesús Enrique Finol Finol, fiscaal nummer PENDIENTE-NIF, gevestigd te Calle Castelví 7, 1D, 50004 Zaragoza, España, handelend onder de naam NX036. Voor privacyvragen of om je rechten uit te oefenen, schrijf naar support@nx036.com."]}, {"h": "Welke gegevens we verzamelen", "p": ["Uit je account: voor- en achternaam, e-mail, telefoon, bedrijf (indien opgegeven), land en taal. Uit je bestellingen: verzend- en factuuradres, bestelinhoud en betaalgeschiedenis. Uit wat je publiceert: de reviews die je schrijft, met je weergavenaam en land. Uit het gebruik: IP-adres, apparaat en bezochte pagina’s. We vragen geen bijzondere categorieën gegevens (gezondheid, overtuigingen, biometrie) en willen die ook niet."]}, {"h": "Waarvoor en op welke rechtsgrond", "p": ["Je account aanmaken en beheren, bestellingen verwerken en verzenden, innen en ondersteunen: uitvoering van de overeenkomst. Facturatie en belastingen: wettelijke verplichting. Fraudepreventie en beveiliging: gerechtvaardigd belang. Niet-essentiële cookies en commerciële berichten: jouw toestemming, altijd intrekbaar."]}, {"h": "Met wie we ze delen", "p": ["Met de leveranciers die nodig zijn om je te bedienen, elk als verwerker en alleen met het strikt noodzakelijke: betaalproviders (Stripe, PayPal), transport en douane, e-mail en infrastructuur. We verkopen je gegevens niet en geven ze niet door voor advertenties van derden."]}, {"h": "Je gegevens verlaten de Europese Unie", "p": ["Bestellingen worden vanuit China verzonden. Om je pakket te bezorgen heeft de vervoerder je naam, volledige adres, postcode, telefoon en e-mail nodig — en ontvangt die ook. Dat is een internationale doorgifte naar een land zonder adequaatheidsbesluit, gebaseerd op de noodzaak om de door jou gevraagde koopovereenkomst uit te voeren (art. 49.1.b AVG) en ondersteund door modelcontractbepalingen met de vervoerder. Zonder die doorgifte is bezorging onmogelijk."]}, {"h": "Hoe lang we ze bewaren", "p": ["Accountgegevens zolang je het account openhoudt. Facturen en fiscale gegevens gedurende de termijnen die de Spaanse wet voorschrijft (zes jaar), ook als je je account sluit: die plicht kunnen we niet omzeilen. Technische beveiligingslogs 12 maanden. Verwijder je je account, dan wordt al het overige gewist of onomkeerbaar geanonimiseerd."]}, {"h": "Wat je van ons kunt eisen", "p": ["Inzage, correctie, wissing, bezwaar tegen verwerking, beperking en overdracht naar een andere dienst (dataportabiliteit). En het intrekken van elke gegeven toestemming, zonder gevolgen voor wat eerder gebeurde.", "Vanuit je profiel kun je een volledige kopie van je gegevens als JSON downloaden en je account zelf verwijderen, zonder iemand om toestemming te vragen. Voor de rest: schrijf naar support@nx036.com; we antwoorden binnen een maand.", "Vind je dat we ons werk niet goed hebben gedaan, dan kun je klagen bij de Spaanse gegevensbeschermingsautoriteit AEPD (www.aepd.es), onze toezichthoudende autoriteit, of bij de toezichthouder van het land waar je woont. Wat jou het beste uitkomt."]}, {"h": "Cookies", "p": ["We gebruiken technisch noodzakelijke cookies en, alleen met jouw toestemming, analyse- en marketingcookies. Je kunt je keuze altijd wijzigen of intrekken via de link in de voettekst. De details, cookie voor cookie, staan in het cookiebeleid."]}, {"h": "Geautomatiseerde besluiten", "p": ["We nemen geen geautomatiseerde besluiten met rechtsgevolgen voor jou of die je aanmerkelijk treffen. Geen profilering met dat doel."]}, {"h": "Minderjarigen", "p": ["Het platform richt zich niet op kinderen onder 14 jaar en we maken bewust geen accounts voor hen aan. Vinden we er een, dan verwijderen we die."]}]}','2026-08-15'),
('terms','es','Términos y condiciones de uso','{"intro": "Estos términos regulan el acceso y el uso de la plataforma NX036 y forman un contrato entre tú y nosotros. Léelos: al crear una cuenta declaras haberlos leído y aceptado. Están escritos para poder comprobarse — si algo de aquí no se corresponde con lo que hacemos, es un error nuestro y queremos saberlo.", "sections": [{"h": "Quiénes somos", "p": ["El titular de la plataforma es Jesús Enrique Finol Finol, con NIF PENDIENTE-NIF y domicilio en Calle Castelví 7, 1D, 50004 Zaragoza, España, que opera bajo el nombre comercial NX036. Puedes escribirnos en cualquier momento a support@nx036.com."]}, {"h": "A quién se aplican estos términos", "p": ["La plataforma la usan dos tipos de clientes muy distintos y no se les puede aplicar lo mismo, así que estos términos distinguen expresamente entre ambos:", "Eres CONSUMIDOR si compras para tu uso personal, fuera de cualquier actividad profesional o empresarial. Te amparan íntegramente los derechos de la normativa de consumo, y nada de este contrato los limita ni los sustituye. Las secciones que te reconocen esos derechos prevalecen sobre cualquier otra que pudiera contradecirlas.", "Eres EMPRESA O REVENDEDOR si actúas en el marco de una actividad profesional, lo que incluye a quien compra para revender, integra la plataforma con su propia tienda o usa nuestra API. En ese caso no te aplican los derechos de consumo —porque legalmente no eres consumidor— y sí te aplican las obligaciones específicas de la sección correspondiente.", "Si tienes dudas sobre en qué categoría estás, escríbenos antes de contratar. En caso de conflicto interpretativo, y cuando concurran indicios de ambas condiciones, se aplicará el régimen de consumidor por ser el más protector."]}, {"h": "Qué es la plataforma y qué no es", "p": ["NX036 es una plataforma tecnológica que da acceso a un catálogo de productos de proveedores, gestiona los pedidos y coordina su envío y su despacho aduanero.", "Cuando el pedido lo hace un consumidor en nuestro escaparate, actuamos como vendedor y respondemos como tal frente a él, con todo lo que eso implica.", "Cuando un revendedor usa la plataforma para servir pedidos a SUS clientes, la venta a esos clientes finales es suya, no nuestra: nosotros le vendemos a él y le prestamos el servicio logístico. Es él quien contrata con su comprador, quien emite su factura, quien atiende su postventa y quien responde de las obligaciones legales de esa venta.", "No fabricamos los productos. Cuando la normativa lo exige, actuamos como operador económico en la Unión y esa información figura en la ficha de cada producto y en la factura."]}, {"h": "Tu cuenta", "p": ["Para usar la plataforma necesitas una cuenta, ser mayor de edad y tener capacidad para contratar. Los datos que nos facilites deben ser veraces y estar al día; si dejan de serlo, actualízalos.", "Eres responsable de la confidencialidad de tus credenciales y de la actividad que se realice con tu cuenta. Si sospechas de un acceso no autorizado, avísanos de inmediato y cambia tu contraseña. Ofrecemos verificación en dos pasos y te recomendamos activarla.", "Una cuenta es personal e intransferible. No puedes cederla, revenderla ni compartir el acceso con terceros ajenos a tu organización."]}, {"h": "Precios, pagos e impuestos", "p": ["Los precios se muestran en la divisa que tengas activa, con los impuestos y el coste de envío desglosados antes de confirmar. El importe que se te cobra es el que aparece en ese resumen.", "Los pagos se procesan a través de proveedores especializados (Stripe, PayPal) o con el saldo de tu monedero. No almacenamos los datos completos de tu tarjeta.", "Los precios pueden cambiar en cualquier momento, pero nunca con efecto retroactivo: el pedido ya confirmado mantiene el precio al que se confirmó. Las suscripciones se renuevan según el periodo contratado hasta que las canceles.", "Los aranceles e impuestos de importación que correspondan al destino se calculan y se muestran antes de pagar. Si el destino exige trámites adicionales que dependan del destinatario, te lo indicaremos."]}, {"h": "Pedidos, envíos y aduanas", "p": ["Un pedido queda perfeccionado cuando lo confirmamos, no antes. Podemos rechazar o cancelar un pedido —devolviendo íntegramente lo cobrado— si el producto ha dejado de estar disponible, si hay un error manifiesto de precio, si el destino no es servible o si detectamos un uso fraudulento.", "Los plazos de entrega que mostramos son estimaciones basadas en la información del transportista, no compromisos de fecha cierta, salvo que expresamente se indique lo contrario.", "Los envíos internacionales están sujetos a los controles aduaneros del país de destino. Para que el paquete llegue, el transportista y las autoridades reciben los datos del destinatario y de la mercancía, tal y como se detalla en la política de privacidad.", "Algunos productos no pueden enviarse a determinados destinos por restricciones legales o del transportista. La plataforma no permite completar esos pedidos."]}, {"h": "Si eres consumidor: tus derechos", "p": ["Tienes derecho a desistir del contrato en el plazo de CATORCE (14) días naturales desde que recibes el producto, sin necesidad de justificarlo y sin penalización. Puedes comunicárnoslo por cualquier medio inequívoco, incluido un correo a support@nx036.com. Los detalles y las excepciones legales están en nuestra política de desistimiento.", "Los productos cuentan con la garantía legal de conformidad de TRES (3) años desde la entrega, conforme a la legislación española. Si el producto no es conforme, tienes derecho a su reparación o sustitución y, cuando proceda, a la rebaja del precio o a la resolución del contrato. Durante los dos primeros años se presume que la falta de conformidad ya existía en la entrega, de modo que no tienes que demostrarlo.", "Ninguna cláusula de estos términos limita, excluye ni condiciona estos derechos. Si alguna pudiera interpretarse en ese sentido, se tendrá por no puesta en lo que a ti respecta.", "Si algo no se ha resuelto a tu satisfacción, puedes acudir a una entidad de resolución alternativa de litigios (RAL) acreditada, a la red de Centros Europeos del Consumidor (ECC-Net) si compras desde otro país de la Unión, o a las autoridades de consumo de tu país de residencia."]}, {"h": "Si eres empresa o revendedor: tus obligaciones", "p": ["Cuando revendes a tus propios clientes, TÚ eres el vendedor frente a ellos. Te corresponde a ti informarles conforme a la normativa aplicable, emitir la factura, atender su desistimiento y su garantía legal, y cumplir las obligaciones fiscales de esa venta.", "Te comprometes a describir los productos de forma veraz y a no atribuirles características, certificaciones u orígenes que no tengan, así como a respetar los derechos de marca y de propiedad intelectual de terceros en tus materiales de venta.", "INDEMNIDAD. Nos mantendrás indemnes —a nosotros, a nuestro personal y a nuestros proveedores— frente a cualquier reclamación, sanción, daño o gasto, incluidos los honorarios razonables de defensa jurídica, que traiga causa de tu incumplimiento de estos términos, de la normativa aplicable a tu actividad, o de la relación entre tú y tus clientes finales. Esta obligación subsiste tras la terminación del contrato.", "Si integras la plataforma mediante nuestra API o nuestros conectores, respetarás los límites de uso publicados y no la emplearás para replicar el catálogo con fines ajenos a la reventa pactada."]}, {"h": "Qué pasa si algo sale mal", "p": ["Si el pedido no llega, llega dañado, llega incompleto o no se corresponde con lo pedido, comunícanoslo desde tu cuenta o escribiendo a support@nx036.com, indicando el número de pedido. Cuanto antes nos llegue, antes podremos reclamar al transportista, que tiene plazos propios.", "Abriremos una incidencia y te informaremos de su curso. Según el caso, la solución será el reenvío del producto, su sustitución o el reembolso de lo pagado; cuando la responsabilidad sea del transportista, gestionaremos la reclamación con él.", "Los reembolsos se realizan al mismo medio de pago que usaste, salvo que acordemos otro. El plazo depende de tu entidad, no de nosotros, una vez emitida la orden.", "Si el problema es una interrupción del servicio o un error de la plataforma, comunícanoslo igual: las incidencias técnicas también se registran y se responden."]}, {"h": "Nuestra responsabilidad", "p": ["Respondemos del correcto cumplimiento de las obligaciones que asumimos en estos términos, conforme a la ley aplicable.", "NADA DE ESTE CONTRATO EXCLUYE NI LIMITA nuestra responsabilidad por dolo, por negligencia grave, por daños personales, por la responsabilidad derivada de productos defectuosos, ni por cualquier otra que la ley no permita excluir. Cualquier limitación de esta sección se entiende sujeta a ese límite.", "Frente a CLIENTES QUE NO SON CONSUMIDORES y en la máxima medida permitida por la ley: no respondemos del lucro cesante, la pérdida de negocio, de clientela, de datos o de oportunidad, ni de daños indirectos o consecuenciales; y nuestra responsabilidad total acumulada por cualquier reclamación queda limitada al importe que nos hayas abonado en los doce meses anteriores al hecho que la origine.", "No respondemos del uso que hagas de la plataforma en contra de estos términos o de la ley, ni de las obligaciones que te correspondan a ti frente a tus propios clientes."]}, {"h": "Disponibilidad del servicio", "p": ["Trabajamos para que la plataforma esté disponible de forma continuada, pero no garantizamos una disponibilidad ininterrumpida ni libre de errores. Puede haber paradas por mantenimiento, actualizaciones o causas ajenas a nosotros.", "Cuando el mantenimiento sea programado y vaya a afectar al servicio, procuraremos avisar con antelación razonable y realizarlo en las franjas de menor uso.", "Podemos modificar, suspender o retirar funcionalidades. Si una modificación te perjudica de forma sustancial y tienes una suscripción en vigor, podrás cancelarla con reembolso de la parte no consumida."]}, {"h": "Uso aceptable y suspensión", "p": ["No puedes usar la plataforma para fines ilícitos, para vulnerar derechos de terceros, para introducir código malicioso, para intentar acceder a datos o cuentas ajenas, ni para realizar ingeniería inversa, extracción masiva de datos o cualquier uso que degrade el servicio.", "Podemos suspender o cerrar una cuenta que incumpla estos términos o la ley, o cuando exista una sospecha fundada de fraude. Salvo que la urgencia o la ley lo impidan, te avisaremos antes e indicaremos el motivo, y podrás alegar lo que estimes oportuno.", "La suspensión no te libera de las cantidades ya devengadas ni afecta a los pedidos en curso, que se completarán o se reembolsarán según corresponda."]}, {"h": "Propiedad intelectual", "p": ["La plataforma, su software, su diseño, sus marcas y los contenidos que elaboramos son nuestros o de quienes nos han licenciado su uso. Tu cuenta te da derecho a usar el servicio, no a apropiarte de ninguno de esos elementos.", "Las imágenes y descripciones del catálogo se ponen a tu disposición para vender los productos adquiridos a través de la plataforma. Ese uso no te convierte en titular de derecho alguno sobre ellas ni te autoriza a emplearlas con otros fines.", "Los contenidos que tú aportes siguen siendo tuyos; al publicarlos nos concedes la licencia estrictamente necesaria para prestarte el servicio."]}, {"h": "Fuerza mayor", "p": ["No responderemos del incumplimiento o del retraso que traiga causa de circunstancias fuera de nuestro control razonable: catástrofes naturales, conflictos armados, disturbios, epidemias, huelgas ajenas a nuestra plantilla, decisiones de autoridades, cierres de fronteras o de aduanas, fallos generalizados de redes de telecomunicaciones o de suministro eléctrico.", "Si la circunstancia se prolonga más de treinta días, cualquiera de las partes podrá resolver el contrato afectado, con reembolso de lo pagado y no prestado. Esta cláusula no ampara la simple dificultad económica ni el encarecimiento de los costes."]}, {"h": "Duración, baja y cancelación", "p": ["El contrato está en vigor mientras mantengas tu cuenta. Puedes darte de baja cuando quieras desde tu perfil, sin dar explicaciones y sin penalización.", "La baja no cancela por sí sola una suscripción en curso ni los pedidos ya confirmados. Conservamos la documentación fiscal el tiempo que exige la ley, según se detalla en la política de privacidad.", "Las cláusulas que por su naturaleza deban sobrevivir a la terminación —indemnidad, responsabilidad, propiedad intelectual, ley aplicable y jurisdicción— seguirán en vigor."]}, {"h": "Cambios en estos términos", "p": ["Podemos modificar estos términos para adaptarlos a cambios legales, técnicos o del servicio. Publicaremos la nueva versión con su fecha y avisaremos por correo electrónico a todas las cuentas activas.", "Si no estás de acuerdo con la nueva versión, puedes darte de baja antes de que empiece a aplicarse. Los pedidos confirmados con anterioridad se rigen por la versión vigente cuando se confirmaron."]}, {"h": "Nulidad parcial", "p": ["Si una autoridad competente declara nula o inaplicable alguna cláusula, esa cláusula se sustituirá por otra válida de efecto equivalente en lo que la ley permita, y el resto del contrato seguirá siendo plenamente vigente."]}, {"h": "Ley aplicable y resolución de conflictos", "p": ["Estos términos se rigen por la ley del país donde tenemos nuestro domicilio social, sin perjuicio de las normas imperativas que resulten aplicables.", "Si eres CONSUMIDOR, esta elección no te priva de la protección que te otorgan las normas imperativas de tu país de residencia habitual, y podrás demandar y ser demandado ante los tribunales de tu domicilio.", "Si NO eres consumidor, las partes se someten a los juzgados y tribunales de nuestro domicilio social, con renuncia a cualquier otro fuero que pudiera corresponderles.", "Antes de acudir a los tribunales te pedimos que nos escribas a support@nx036.com: la mayoría de los problemas se resuelven así, y más rápido."]}]}','2026-08-15'),
('terms','en','Terms and conditions of use','{"intro": "These terms govern access to and use of the NX036 platform and form a contract between you and us. Please read them: by creating an account you confirm you have read and accepted them. They are written to be checked — if anything here does not match what we actually do, that is our mistake and we want to hear about it.", "sections": [{"h": "Who we are", "p": ["The platform is operated by Jesús Enrique Finol Finol, tax ID PENDIENTE-NIF, with address at Calle Castelví 7, 1D, 50004 Zaragoza, España, trading under the name NX036. You can write to us at any time at support@nx036.com."]}, {"h": "Who these terms apply to", "p": ["Two very different kinds of customer use the platform and the same rules cannot apply to both, so these terms distinguish between them expressly:", "You are a CONSUMER if you buy for your personal use, outside any professional or business activity. Consumer protection law applies to you in full, and nothing in this contract limits or replaces it. The sections recognising those rights prevail over any other that might contradict them.", "You are a BUSINESS OR RESELLER if you act within a professional activity, which includes buying to resell, integrating the platform with your own shop, or using our API. In that case consumer rights do not apply to you —because in law you are not a consumer— and the specific obligations of the relevant section do.", "If you are unsure which category you fall into, write to us before contracting. Where there is a dispute over interpretation, and indications of both conditions are present, the consumer regime will apply as the more protective one."]}, {"h": "What the platform is and what it is not", "p": ["NX036 is a technology platform that gives access to a catalogue of supplier products, manages orders and coordinates their shipping and customs clearance.", "When the order is placed by a consumer in our own storefront, we act as the seller and we answer as such, with everything that entails.", "When a reseller uses the platform to fulfil orders for THEIR customers, the sale to those end customers is theirs, not ours: we sell to the reseller and provide the logistics service. It is the reseller who contracts with their buyer, issues their invoice, handles their after-sales and answers for the legal obligations of that sale.", "We do not manufacture the products. Where the law requires it we act as economic operator in the Union, and that information appears on each product page and on the invoice."]}, {"h": "Your account", "p": ["To use the platform you need an account, to be of legal age and to have capacity to contract. The details you give us must be truthful and up to date; if they stop being so, update them.", "You are responsible for keeping your credentials confidential and for the activity carried out with your account. If you suspect unauthorised access, tell us immediately and change your password. We offer two-step verification and we recommend enabling it.", "An account is personal and non-transferable. You may not assign it, resell it or share access with third parties outside your organisation."]}, {"h": "Prices, payments and taxes", "p": ["Prices are shown in your active currency, with taxes and shipping costs itemised before you confirm. The amount charged is the one shown in that summary.", "Payments are processed through specialised providers (Stripe, PayPal) or with your wallet balance. We do not store your full card details.", "Prices may change at any time, but never retroactively: an order already confirmed keeps the price at which it was confirmed. Subscriptions renew for the contracted period until you cancel them.", "Import duties and taxes applicable to the destination are calculated and shown before you pay. If the destination requires additional formalities from the recipient, we will tell you."]}, {"h": "Orders, shipping and customs", "p": ["An order is concluded when we confirm it, not before. We may reject or cancel an order —refunding in full what was charged— if the product is no longer available, if there is a manifest pricing error, if the destination cannot be served, or if we detect fraudulent use.", "Delivery times we display are estimates based on carrier information, not firm date commitments, unless expressly stated otherwise.", "International shipments are subject to the customs controls of the destination country. For the parcel to arrive, the carrier and the authorities receive the recipient''s and the goods'' details, as set out in the privacy policy.", "Some products cannot be shipped to certain destinations because of legal or carrier restrictions. The platform does not allow such orders to be completed."]}, {"h": "If you are a consumer: your rights", "p": ["You have the right to withdraw from the contract within FOURTEEN (14) calendar days of receiving the product, without giving any reason and without penalty. You may tell us by any unequivocal means, including an email to support@nx036.com. The details and the statutory exceptions are in our withdrawal policy.", "Products carry the statutory guarantee of conformity of THREE (3) years from delivery, under Spanish law. If the product is not in conformity, you are entitled to have it repaired or replaced and, where appropriate, to a price reduction or to terminate the contract. For the first two years the lack of conformity is presumed to have existed at delivery, so you do not have to prove it.", "No clause in these terms limits, excludes or conditions those rights. If any could be read that way, it shall be treated as not written as far as you are concerned.", "If something has not been resolved to your satisfaction, you may turn to an accredited alternative dispute resolution (ADR) body, to the European Consumer Centres Network (ECC-Net) if you buy from another EU country, or to the consumer authorities of your country of residence."]}, {"h": "If you are a business or reseller: your obligations", "p": ["When you resell to your own customers, YOU are the seller towards them. It is for you to inform them as the applicable law requires, to issue the invoice, to handle their withdrawal and statutory guarantee, and to meet the tax obligations of that sale.", "You undertake to describe the products truthfully and not to attribute to them characteristics, certifications or origins they do not have, and to respect third-party trademark and intellectual property rights in your sales materials.", "INDEMNITY. You shall hold us harmless —us, our staff and our suppliers— against any claim, penalty, damage or expense, including reasonable legal defence costs, arising from your breach of these terms, of the law applicable to your activity, or from the relationship between you and your end customers. This obligation survives termination of the contract.", "If you integrate the platform through our API or our connectors, you will respect the published usage limits and will not use it to replicate the catalogue for purposes other than the agreed resale."]}, {"h": "What happens if something goes wrong", "p": ["If the order does not arrive, arrives damaged, arrives incomplete or does not match what was ordered, tell us from your account or by writing to support@nx036.com, quoting the order number. The sooner we hear, the sooner we can claim against the carrier, who has deadlines of its own.", "We will open an incident and keep you informed of its progress. Depending on the case, the remedy will be reshipment, replacement or refund of what you paid; where the carrier is responsible, we will handle the claim with them.", "Refunds are made to the same payment method you used, unless we agree otherwise. The timing depends on your bank, not on us, once the order has been issued.", "If the problem is a service interruption or a platform error, tell us just the same: technical incidents are logged and answered too."]}, {"h": "Our liability", "p": ["We are liable for properly performing the obligations we assume in these terms, in accordance with applicable law.", "NOTHING IN THIS CONTRACT EXCLUDES OR LIMITS our liability for wilful misconduct, gross negligence, personal injury, liability for defective products, or any other liability the law does not permit to be excluded. Any limitation in this section is subject to that boundary.", "Towards CUSTOMERS WHO ARE NOT CONSUMERS and to the fullest extent permitted by law: we are not liable for loss of profit, loss of business, of goodwill, of data or of opportunity, nor for indirect or consequential damages; and our total aggregate liability for any claim is limited to the amount you have paid us in the twelve months preceding the event giving rise to it.", "We are not liable for your use of the platform contrary to these terms or to the law, nor for the obligations that fall on you towards your own customers."]}, {"h": "Service availability", "p": ["We work to keep the platform continuously available, but we do not guarantee uninterrupted or error-free availability. There may be downtime for maintenance, updates or causes beyond our control.", "Where maintenance is scheduled and will affect the service, we will try to give reasonable notice and to carry it out during low-usage periods.", "We may modify, suspend or withdraw features. If a change substantially harms you and you hold a current subscription, you may cancel it with a refund of the unused portion."]}, {"h": "Acceptable use and suspension", "p": ["You may not use the platform for unlawful purposes, to infringe third-party rights, to introduce malicious code, to attempt to access other people''s data or accounts, or to carry out reverse engineering, mass data extraction or any use that degrades the service.", "We may suspend or close an account that breaches these terms or the law, or where there is a well-founded suspicion of fraud. Unless urgency or the law prevents it, we will notify you beforehand stating the reason, and you may make whatever representations you see fit.", "Suspension does not release you from amounts already accrued, nor does it affect orders in progress, which will be completed or refunded as appropriate."]}, {"h": "Intellectual property", "p": ["The platform, its software, design, trademarks and the content we produce belong to us or to those who have licensed their use to us. Your account gives you the right to use the service, not to appropriate any of those elements.", "Catalogue images and descriptions are made available to you in order to sell the products acquired through the platform. That use does not make you the owner of any right over them nor authorise you to use them for other purposes.", "Content you contribute remains yours; by publishing it you grant us the licence strictly necessary to provide the service to you."]}, {"h": "Force majeure", "p": ["We will not be liable for failure or delay caused by circumstances beyond our reasonable control: natural disasters, armed conflict, civil unrest, epidemics, strikes outside our own workforce, decisions of authorities, border or customs closures, or widespread failures of telecommunications networks or of electricity supply.", "If the circumstance lasts more than thirty days, either party may terminate the affected contract, with a refund of what has been paid and not provided. This clause does not cover mere economic hardship or increased costs."]}, {"h": "Duration, closing your account and cancellation", "p": ["The contract is in force for as long as you keep your account. You may close it whenever you wish from your profile, without giving reasons and without penalty.", "Closing your account does not by itself cancel a current subscription or orders already confirmed. We keep tax documentation for as long as the law requires, as detailed in the privacy policy.", "Clauses which by their nature must survive termination —indemnity, liability, intellectual property, governing law and jurisdiction— will remain in force."]}, {"h": "Changes to these terms", "p": ["We may amend these terms to adapt them to legal, technical or service changes. We will publish the new version with its date and notify all active accounts by email.", "If you do not agree with the new version, you may close your account before it takes effect. Orders confirmed beforehand are governed by the version in force when they were confirmed."]}, {"h": "Severability", "p": ["If a competent authority declares any clause void or unenforceable, that clause will be replaced by a valid one of equivalent effect so far as the law allows, and the rest of the contract will remain fully in force."]}, {"h": "Governing law and dispute resolution", "p": ["These terms are governed by the law of the country where we are domiciled, without prejudice to any mandatory rules that may apply.", "If you are a CONSUMER, this choice does not deprive you of the protection afforded by the mandatory rules of your country of habitual residence, and you may sue and be sued in the courts of your domicile.", "If you are NOT a consumer, the parties submit to the courts of our domicile, waiving any other jurisdiction that might apply.", "Before going to court, please write to us at support@nx036.com: most problems are solved that way, and faster."]}]}','2026-08-15'),
('terms','pt','Termos e condições de utilização','{"intro": "Estes termos regulam o acesso e a utilização da plataforma NX036 e formam um contrato entre si e nós. Leia-os: ao criar uma conta declara tê-los lido e aceite. Estão escritos para poderem ser verificados — se algo aqui não corresponder ao que fazemos, é um erro nosso e queremos sabê-lo.", "sections": [{"h": "Quem somos", "p": ["O titular da plataforma é Jesús Enrique Finol Finol, com NIF PENDIENTE-NIF e domicílio em Calle Castelví 7, 1D, 50004 Zaragoza, España, que opera sob o nome comercial NX036. Pode escrever-nos a qualquer momento para support@nx036.com."]}, {"h": "A quem se aplicam estes termos", "p": ["A plataforma é utilizada por dois tipos de clientes muito diferentes e não se lhes pode aplicar o mesmo, pelo que estes termos distinguem expressamente entre ambos:", "É CONSUMIDOR se comprar para uso pessoal, fora de qualquer atividade profissional ou empresarial. Beneficia integralmente dos direitos da legislação de consumo, e nada neste contrato os limita ou substitui. As secções que lhe reconhecem esses direitos prevalecem sobre qualquer outra que possa contradizê-las.", "É EMPRESA OU REVENDEDOR se atuar no âmbito de uma atividade profissional, o que inclui quem compra para revender, integra a plataforma na sua própria loja ou usa a nossa API. Nesse caso não lhe aplicam os direitos de consumo —porque legalmente não é consumidor— e aplicam-se as obrigações específicas da secção correspondente.", "Se tiver dúvidas sobre em que categoria se enquadra, escreva-nos antes de contratar. Em caso de conflito interpretativo, e havendo indícios de ambas as condições, aplicar-se-á o regime de consumidor por ser o mais protetor."]}, {"h": "O que é a plataforma e o que não é", "p": ["A NX036 é uma plataforma tecnológica que dá acesso a um catálogo de produtos de fornecedores, gere as encomendas e coordena o seu envio e desalfandegamento.", "Quando a encomenda é feita por um consumidor na nossa loja, atuamos como vendedor e respondemos como tal perante ele, com tudo o que isso implica.", "Quando um revendedor usa a plataforma para servir encomendas aos SEUS clientes, a venda a esses clientes finais é dele, não nossa: nós vendemos-lhe a ele e prestamos-lhe o serviço logístico. É ele quem contrata com o seu comprador, quem emite a sua fatura, quem trata do pós-venda e quem responde pelas obrigações legais dessa venda.", "Não fabricamos os produtos. Quando a lei o exige, atuamos como operador económico na União e essa informação consta da ficha de cada produto e da fatura."]}, {"h": "A sua conta", "p": ["Para usar a plataforma precisa de uma conta, de ser maior de idade e de ter capacidade para contratar. Os dados que nos fornecer devem ser verdadeiros e estar atualizados; se deixarem de o ser, atualize-os.", "É responsável pela confidencialidade das suas credenciais e pela atividade realizada com a sua conta. Se suspeitar de um acesso não autorizado, avise-nos de imediato e altere a palavra-passe. Disponibilizamos verificação em duas etapas e recomendamos que a ative.", "Uma conta é pessoal e intransmissível. Não pode cedê-la, revendê-la nem partilhar o acesso com terceiros alheios à sua organização."]}, {"h": "Preços, pagamentos e impostos", "p": ["Os preços são apresentados na divisa que tiver ativa, com os impostos e o custo de envio discriminados antes de confirmar. O valor cobrado é o que aparece nesse resumo.", "Os pagamentos são processados através de fornecedores especializados (Stripe, PayPal) ou com o saldo da sua carteira. Não armazenamos os dados completos do seu cartão.", "Os preços podem mudar a qualquer momento, mas nunca com efeito retroativo: a encomenda já confirmada mantém o preço a que foi confirmada. As subscrições renovam-se conforme o período contratado até as cancelar.", "Os direitos aduaneiros e impostos de importação aplicáveis ao destino são calculados e mostrados antes do pagamento. Se o destino exigir formalidades adicionais a cargo do destinatário, indicá-lo-emos."]}, {"h": "Encomendas, envios e alfândega", "p": ["Uma encomenda fica concluída quando a confirmamos, não antes. Podemos recusar ou cancelar uma encomenda —devolvendo integralmente o cobrado— se o produto deixar de estar disponível, se houver um erro manifesto de preço, se o destino não for servível ou se detetarmos uma utilização fraudulenta.", "Os prazos de entrega que mostramos são estimativas baseadas na informação da transportadora, não compromissos de data certa, salvo indicação expressa em contrário.", "Os envios internacionais estão sujeitos aos controlos aduaneiros do país de destino. Para que a encomenda chegue, a transportadora e as autoridades recebem os dados do destinatário e da mercadoria, conforme detalhado na política de privacidade.", "Alguns produtos não podem ser enviados para determinados destinos por restrições legais ou da transportadora. A plataforma não permite concluir essas encomendas."]}, {"h": "Se é consumidor: os seus direitos", "p": ["Tem direito a resolver o contrato no prazo de CATORZE (14) dias corridos desde que recebe o produto, sem necessidade de justificação e sem penalização. Pode comunicá-lo por qualquer meio inequívoco, incluindo um e-mail para support@nx036.com. Os detalhes e as exceções legais estão na nossa política de livre resolução.", "Os produtos beneficiam da garantia legal de conformidade de TRÊS (3) anos desde a entrega, nos termos da lei espanhola. Se o produto não estiver conforme, tem direito à sua reparação ou substituição e, quando aplicável, à redução do preço ou à resolução do contrato. Nos dois primeiros anos presume-se que a falta de conformidade já existia na entrega, pelo que não tem de o demonstrar.", "Nenhuma cláusula destes termos limita, exclui ou condiciona estes direitos. Se alguma puder ser interpretada nesse sentido, ter-se-á por não escrita no que lhe diz respeito.", "Se algo não tiver sido resolvido a seu contento, pode recorrer a uma entidade de resolução alternativa de litígios (RAL) acreditada, à rede de Centros Europeus do Consumidor (ECC-Net) se comprar a partir de outro país da União, ou às autoridades de consumo do seu país de residência."]}, {"h": "Se é empresa ou revendedor: as suas obrigações", "p": ["Quando revende aos seus próprios clientes, É VOCÊ o vendedor perante eles. Cabe-lhe informá-los nos termos da lei aplicável, emitir a fatura, tratar da sua livre resolução e da garantia legal, e cumprir as obrigações fiscais dessa venda.", "Compromete-se a descrever os produtos de forma verdadeira e a não lhes atribuir características, certificações ou origens que não tenham, bem como a respeitar os direitos de marca e de propriedade intelectual de terceiros nos seus materiais de venda.", "INDEMNIZAÇÃO. Manter-nos-á indemnes —a nós, ao nosso pessoal e aos nossos fornecedores— perante qualquer reclamação, sanção, dano ou despesa, incluindo honorários razoáveis de defesa jurídica, que decorra do seu incumprimento destes termos, da lei aplicável à sua atividade, ou da relação entre si e os seus clientes finais. Esta obrigação subsiste após a cessação do contrato.", "Se integrar a plataforma através da nossa API ou dos nossos conectores, respeitará os limites de utilização publicados e não a usará para replicar o catálogo com fins alheios à revenda acordada."]}, {"h": "O que acontece se algo correr mal", "p": ["Se a encomenda não chegar, chegar danificada, chegar incompleta ou não corresponder ao pedido, comunique-nos a partir da sua conta ou escrevendo para support@nx036.com, indicando o número da encomenda. Quanto mais cedo soubermos, mais cedo podemos reclamar junto da transportadora, que tem prazos próprios.", "Abriremos uma ocorrência e informá-lo-emos do seu andamento. Consoante o caso, a solução será o reenvio do produto, a sua substituição ou o reembolso do que pagou; quando a responsabilidade for da transportadora, trataremos da reclamação com ela.", "Os reembolsos são feitos para o mesmo meio de pagamento que usou, salvo acordo em contrário. O prazo depende da sua instituição, não de nós, uma vez emitida a ordem.", "Se o problema for uma interrupção do serviço ou um erro da plataforma, comunique-nos igualmente: as ocorrências técnicas também são registadas e respondidas."]}, {"h": "A nossa responsabilidade", "p": ["Respondemos pelo correto cumprimento das obrigações que assumimos nestes termos, nos termos da lei aplicável.", "NADA NESTE CONTRATO EXCLUI OU LIMITA a nossa responsabilidade por dolo, por negligência grosseira, por danos pessoais, pela responsabilidade decorrente de produtos defeituosos, nem por qualquer outra que a lei não permita excluir. Qualquer limitação desta secção entende-se sujeita a esse limite.", "Perante CLIENTES QUE NÃO SÃO CONSUMIDORES e na máxima medida permitida por lei: não respondemos por lucros cessantes, perda de negócio, de clientela, de dados ou de oportunidade, nem por danos indiretos ou consequenciais; e a nossa responsabilidade total acumulada por qualquer reclamação fica limitada ao montante que nos tenha pago nos doze meses anteriores ao facto que a origina.", "Não respondemos pelo uso que faça da plataforma contra estes termos ou a lei, nem pelas obrigações que lhe caibam a si perante os seus próprios clientes."]}, {"h": "Disponibilidade do serviço", "p": ["Trabalhamos para que a plataforma esteja disponível de forma contínua, mas não garantimos uma disponibilidade ininterrupta nem isenta de erros. Pode haver paragens por manutenção, atualizações ou causas alheias a nós.", "Quando a manutenção for programada e vier a afetar o serviço, procuraremos avisar com antecedência razoável e realizá-la nos períodos de menor utilização.", "Podemos modificar, suspender ou retirar funcionalidades. Se uma alteração o prejudicar de forma substancial e tiver uma subscrição em vigor, poderá cancelá-la com reembolso da parte não utilizada."]}, {"h": "Utilização aceitável e suspensão", "p": ["Não pode usar a plataforma para fins ilícitos, para violar direitos de terceiros, para introduzir código malicioso, para tentar aceder a dados ou contas alheias, nem para realizar engenharia inversa, extração massiva de dados ou qualquer uso que degrade o serviço.", "Podemos suspender ou encerrar uma conta que incumpra estes termos ou a lei, ou quando exista suspeita fundada de fraude. Salvo se a urgência ou a lei o impedirem, avisá-lo-emos antes indicando o motivo, e poderá alegar o que entender.", "A suspensão não o liberta das quantias já vencidas nem afeta as encomendas em curso, que serão concluídas ou reembolsadas conforme aplicável."]}, {"h": "Propriedade intelectual", "p": ["A plataforma, o seu software, o seu design, as suas marcas e os conteúdos que elaboramos são nossos ou de quem nos licenciou o seu uso. A sua conta dá-lhe o direito de usar o serviço, não de se apropriar de nenhum desses elementos.", "As imagens e descrições do catálogo são colocadas à sua disposição para vender os produtos adquiridos através da plataforma. Esse uso não o torna titular de qualquer direito sobre elas nem o autoriza a empregá-las com outros fins.", "Os conteúdos que contribuir continuam a ser seus; ao publicá-los concede-nos a licença estritamente necessária para lhe prestar o serviço."]}, {"h": "Força maior", "p": ["Não responderemos pelo incumprimento ou atraso decorrente de circunstâncias fora do nosso controlo razoável: catástrofes naturais, conflitos armados, distúrbios, epidemias, greves alheias ao nosso pessoal, decisões de autoridades, encerramento de fronteiras ou alfândegas, falhas generalizadas de redes de telecomunicações ou de fornecimento elétrico.", "Se a circunstância se prolongar por mais de trinta dias, qualquer das partes poderá resolver o contrato afetado, com reembolso do pago e não prestado. Esta cláusula não abrange a simples dificuldade económica nem o encarecimento dos custos."]}, {"h": "Duração, cessação e cancelamento", "p": ["O contrato vigora enquanto mantiver a sua conta. Pode encerrá-la quando quiser a partir do seu perfil, sem dar explicações e sem penalização.", "O encerramento não cancela por si só uma subscrição em curso nem as encomendas já confirmadas. Conservamos a documentação fiscal pelo tempo que a lei exige, conforme detalhado na política de privacidade.", "As cláusulas que pela sua natureza devam sobreviver à cessação —indemnização, responsabilidade, propriedade intelectual, lei aplicável e jurisdição— manter-se-ão em vigor."]}, {"h": "Alterações a estes termos", "p": ["Podemos modificar estes termos para os adaptar a alterações legais, técnicas ou do serviço. Publicaremos a nova versão com a sua data e avisaremos por e-mail todas as contas ativas.", "Se não concordar com a nova versão, pode encerrar a conta antes de esta começar a aplicar-se. As encomendas confirmadas anteriormente regem-se pela versão em vigor quando foram confirmadas."]}, {"h": "Nulidade parcial", "p": ["Se uma autoridade competente declarar nula ou inaplicável alguma cláusula, essa cláusula será substituída por outra válida de efeito equivalente no que a lei permitir, e o restante do contrato manter-se-á plenamente em vigor."]}, {"h": "Lei aplicável e resolução de conflitos", "p": ["Estes termos regem-se pela lei do país onde temos o nosso domicílio, sem prejuízo das normas imperativas que resultem aplicáveis.", "Se for CONSUMIDOR, esta escolha não o priva da proteção que lhe conferem as normas imperativas do seu país de residência habitual, e poderá demandar e ser demandado nos tribunais do seu domicílio.", "Se NÃO for consumidor, as partes submetem-se aos tribunais do nosso domicílio, com renúncia a qualquer outro foro que lhes pudesse caber.", "Antes de recorrer aos tribunais, pedimos-lhe que nos escreva para support@nx036.com: a maioria dos problemas resolve-se assim, e mais depressa."]}]}','2026-08-15'),
('terms','zh','使用条款与条件','{"intro": "本条款规定 NX036 平台的访问与使用,并构成您与我们之间的合同。请阅读:创建账户即表示您已阅读并接受本条款。本条款以可核查的方式撰写 —— 若此处内容与我们的实际做法不符,那是我们的错误,我们希望知晓。", "sections": [{"h": "我们是谁", "p": ["平台的经营者为 Jesús Enrique Finol Finol,税号 PENDIENTE-NIF,地址 Calle Castelví 7, 1D, 50004 Zaragoza, España,以商号 NX036 开展经营。您可随时发送邮件至 support@nx036.com 与我们联系。"]}, {"h": "本条款适用于谁", "p": ["使用平台的客户分为两类,情况差异很大,不能适用相同规则,因此本条款明确区分两者:", "如果您为个人使用而购买,且不属于任何职业或经营活动,则您是消费者。消费者保护法规完整适用于您,本合同的任何内容均不限制或取代该等法规。确认您上述权利的章节,其效力优先于任何可能与之冲突的其他章节。", "如果您在职业活动范围内行事,则您是企业或分销商,包括为转售而购买、将平台接入自有店铺或使用我们 API 的情形。在此情况下,消费者权利不适用于您 —— 因为在法律上您并非消费者 —— 而相应章节规定的特定义务适用于您。", "若您不确定属于哪一类,请在缔约前与我们联系。发生解释争议且同时存在两种身份迹象时,将适用保护力度更强的消费者规则。"]}, {"h": "平台是什么,不是什么", "p": ["NX036 是一个技术平台,提供供应商产品目录的访问,管理订单,并协调其运输与清关。", "当订单由消费者在我们自有店铺下单时,我们作为卖方行事,并以卖方身份对其承担相应责任。", "当分销商使用平台为其自己的客户履行订单时,对该等最终客户的销售属于分销商,而非我们:我们向分销商销售并提供物流服务。与买方缔约、开具发票、处理售后并承担该项销售法定义务的,是分销商本人。", "我们不生产产品。在法规要求时,我们作为欧盟经济经营者行事,该信息载于每件产品的页面及发票之上。"]}, {"h": "您的账户", "p": ["使用平台需要账户,您须已成年并具有缔约能力。您提供的信息须真实且保持更新;若不再准确,请及时更新。", "您应对凭证的保密性及账户下发生的活动负责。若怀疑存在未经授权的访问,请立即通知我们并更改密码。我们提供两步验证,建议您启用。", "账户为个人所有且不可转让。您不得转让、转售账户,亦不得与您组织以外的第三方共享访问权限。"]}, {"h": "价格、支付与税费", "p": ["价格以您启用的币种显示,税费与运费在确认前分项列示。实际收取的金额即为该摘要中显示的金额。", "支付通过专业服务商(Stripe、PayPal)或您的钱包余额处理。我们不存储您的完整银行卡信息。", "价格可能随时变动,但绝不溯及既往:已确认的订单保持其确认时的价格。订阅按所购周期自动续期,直至您取消。", "适用于目的地的关税与进口税费在付款前计算并显示。若目的地要求收件人办理额外手续,我们会予以提示。"]}, {"h": "订单、运输与海关", "p": ["订单于我们确认时成立,在此之前不成立。若产品不再可供、存在明显价格错误、目的地无法配送,或我们发现欺诈性使用,我们可拒绝或取消订单,并全额退还已收款项。", "我们展示的送达时间为基于承运人信息的预估,除非明确另有说明,并非确定日期的承诺。", "国际运输须接受目的地国家的海关查验。为使包裹送达,承运人与主管机关会收到收件人及货物的相关信息,详见隐私政策。", "部分产品因法律或承运人限制,无法发往特定目的地。平台不允许完成此类订单。"]}, {"h": "若您是消费者:您的权利", "p": ["您有权自收到产品之日起十四(14)个自然日内撤回合同,无需说明理由,亦无需承担违约金。您可通过任何明确方式告知我们,包括发送邮件至 support@nx036.com。细节与法定例外情形载于我们的撤回政策。", "依西班牙法律,产品自交付之日起享有三(3)年的法定符合性保证。若产品不符合约定,您有权要求修理或更换,并在适当情况下要求减价或解除合同。前两年推定不符合情形在交付时即已存在,您无需举证。", "本条款的任何条文均不限制、排除或附条件限制上述权利。若某一条文可能被作此解释,则就您而言视为未订立。", "若某事项未能令您满意地解决,您可向经认可的替代性争议解决(ADR)机构、欧洲消费者中心网络(ECC-Net,适用于自欧盟其他国家购买的情形),或您居住国的消费者主管机关寻求帮助。"]}, {"h": "若您是企业或分销商:您的义务", "p": ["当您向自己的客户转售时,对他们而言您就是卖方。依适用法律向其提供信息、开具发票、处理其撤回权与法定保证,并履行该项销售的税务义务,均由您负责。", "您承诺如实描述产品,不为其标注并不具备的特性、认证或产地,并在销售材料中尊重第三方的商标与知识产权。", "补偿义务。因您违反本条款、违反适用于您经营活动的法规,或因您与最终客户之间的关系而产生的任何索赔、处罚、损害或费用(包括合理的法律抗辩费用),您应使我们、我们的员工及供应商免受损害。该义务在合同终止后继续有效。", "若您通过我们的 API 或连接器接入平台,您将遵守已公布的使用限额,不得将其用于复制目录以实现约定转售以外的目的。"]}, {"h": "如果出现问题会怎样", "p": ["若订单未送达、送达时受损、送达不完整或与所订不符,请通过您的账户或发送邮件至 support@nx036.com 告知我们,并注明订单号。我们越早获悉,就能越早向有自身时限的承运人提出索赔。", "我们将开立事件工单并告知处理进展。视情形而定,解决方案为重新发货、更换或退还已付款项;责任在承运人时,由我们与其交涉索赔。", "退款退回您使用的同一支付方式,另有约定的除外。指令发出后,到账时间取决于您的开户机构,而非我们。", "若问题为服务中断或平台错误,同样请告知我们:技术事件也会被记录并予以回复。"]}, {"h": "我们的责任", "p": ["我们依照适用法律,对本条款中所承担义务的正确履行负责。", "本合同的任何内容均不排除或限制我们因故意、重大过失、人身伤害、缺陷产品责任,或法律不允许排除的任何其他责任而承担的责任。本节的任何限制均以该界限为前提。", "对于非消费者客户,在法律允许的最大范围内:我们不对利润损失、业务损失、客户损失、数据损失或机会损失负责,亦不对间接损失或后果性损失负责;且我们就任何索赔的累计责任总额,以引发该索赔的事件发生前十二个月内您向我们支付的金额为限。", "我们不对您违反本条款或法律使用平台的行为负责,亦不对您对自己客户所负的义务负责。"]}, {"h": "服务可用性", "p": ["我们致力于使平台持续可用,但不保证不间断或无差错的可用性。可能因维护、更新或我们无法控制的原因而中断。", "计划内维护将影响服务时,我们将尽力提前合理通知,并安排在使用较少的时段进行。", "我们可修改、暂停或下线功能。若某项变更对您造成实质性不利影响且您持有有效订阅,您可取消订阅并获得未使用部分的退款。"]}, {"h": "可接受使用与账户暂停", "p": ["您不得将平台用于非法目的、侵害第三方权利、植入恶意代码、试图访问他人数据或账户,亦不得进行逆向工程、大规模数据抓取或任何导致服务质量下降的使用。", "对于违反本条款或法律的账户,或存在合理欺诈嫌疑时,我们可暂停或关闭该账户。除非情况紧急或法律另有规定,我们会事先通知并说明理由,您可提出您认为适当的申辩。", "暂停不免除您已产生的应付款项,亦不影响进行中的订单,该等订单将视情况完成或退款。"]}, {"h": "知识产权", "p": ["平台及其软件、设计、商标以及我们制作的内容,归我们或向我们授予使用许可的人所有。您的账户赋予您使用服务的权利,而非占有上述任何要素的权利。", "目录中的图片与描述提供给您,用于销售通过平台购得的产品。该项使用不使您成为其任何权利的权利人,亦不授权您将其用于其他目的。", "您提供的内容仍属于您;发布时您授予我们为向您提供服务所严格必需的许可。"]}, {"h": "不可抗力", "p": ["对于超出我们合理控制范围的情形所导致的不履行或延迟,我们不承担责任:自然灾害、武装冲突、骚乱、疫情、非我方员工的罢工、主管机关的决定、边境或海关关闭、电信网络或电力供应的大范围故障。", "若该情形持续超过三十日,任何一方均可解除受影响的合同,并退还已付但未提供部分的款项。本条款不涵盖单纯的经济困难或成本上涨。"]}, {"h": "期限、注销与终止", "p": ["只要您保留账户,合同即持续有效。您可随时在个人资料页关闭账户,无需说明理由,亦无违约金。", "关闭账户本身不取消进行中的订阅,也不影响已确认的订单。税务文件我们按法律要求的期限保存,详见隐私政策。", "依其性质应在合同终止后继续有效的条款 —— 补偿义务、责任、知识产权、适用法律与管辖 —— 继续有效。"]}, {"h": "本条款的变更", "p": ["我们可修改本条款,以适应法律、技术或服务方面的变化。我们将公布注明日期的新版本,并通过电子邮件通知所有活跃账户。", "若您不同意新版本,可在其生效前关闭账户。此前已确认的订单,适用其确认时有效的版本。"]}, {"h": "部分无效", "p": ["若主管机关宣告某一条款无效或不可执行,则在法律允许的范围内,该条款将由具有同等效力的有效条款替代,合同其余部分继续完全有效。"]}, {"h": "适用法律与争议解决", "p": ["本条款适用我们住所地国家的法律,但不影响可能适用的强制性规范。", "若您是消费者,该选择不剥夺您惯常居住地国家强制性规范给予您的保护,您可在自己住所地法院起诉,亦可在该地被诉。", "若您并非消费者,双方服从我们住所地法院管辖,并放弃其可能享有的任何其他管辖。", "在诉诸法院之前,请先发送邮件至 support@nx036.com:多数问题可以这样解决,而且更快。"]}]}','2026-08-15'),
('terms','fr','Conditions générales d’utilisation','{"intro": "Ces conditions régissent l’accès à la plateforme NX036 et son utilisation, et forment un contrat entre vous et nous. Lisez-les : en créant un compte, vous déclarez en avoir pris connaissance et les accepter. Elles sont écrites pour pouvoir être vérifiées — si quelque chose ici ne correspond pas à ce que nous faisons, c’est une erreur de notre part et nous voulons le savoir.", "sections": [{"h": "Qui nous sommes", "p": ["La plateforme est exploitée par Jesús Enrique Finol Finol, n° fiscal PENDIENTE-NIF, domicilié à Calle Castelví 7, 1D, 50004 Zaragoza, España, exerçant sous le nom commercial NX036. Vous pouvez nous écrire à tout moment à support@nx036.com."]}, {"h": "À qui s’appliquent ces conditions", "p": ["Deux types de clients très différents utilisent la plateforme et on ne peut pas leur appliquer les mêmes règles ; ces conditions distinguent donc expressément les deux :", "Vous êtes CONSOMMATEUR si vous achetez pour votre usage personnel, en dehors de toute activité professionnelle ou commerciale. Le droit de la consommation s’applique intégralement à vous, et rien dans ce contrat ne le limite ni ne le remplace. Les sections qui vous reconnaissent ces droits prévalent sur toute autre qui pourrait les contredire.", "Vous êtes ENTREPRISE OU REVENDEUR si vous agissez dans le cadre d’une activité professionnelle, ce qui inclut celui qui achète pour revendre, intègre la plateforme à sa propre boutique ou utilise notre API. Dans ce cas, les droits des consommateurs ne vous sont pas applicables —car vous n’êtes légalement pas un consommateur— et les obligations spécifiques de la section correspondante le sont.", "Si vous avez un doute sur votre catégorie, écrivez-nous avant de contracter. En cas de conflit d’interprétation, et lorsque des indices des deux qualités coexistent, le régime consommateur s’appliquera comme étant le plus protecteur."]}, {"h": "Ce qu’est la plateforme et ce qu’elle n’est pas", "p": ["NX036 est une plateforme technologique qui donne accès à un catalogue de produits de fournisseurs, gère les commandes et coordonne leur expédition et leur dédouanement.", "Lorsque la commande est passée par un consommateur sur notre propre boutique, nous agissons en qualité de vendeur et répondons comme tel envers lui, avec tout ce que cela implique.", "Lorsqu’un revendeur utilise la plateforme pour servir les commandes de SES clients, la vente à ces clients finaux est la sienne, pas la nôtre : nous lui vendons à lui et lui fournissons le service logistique. C’est lui qui contracte avec son acheteur, émet sa facture, assure son service après-vente et répond des obligations légales de cette vente.", "Nous ne fabriquons pas les produits. Lorsque la réglementation l’exige, nous agissons comme opérateur économique dans l’Union, et cette information figure sur la fiche de chaque produit et sur la facture."]}, {"h": "Votre compte", "p": ["Pour utiliser la plateforme, il vous faut un compte, être majeur et avoir la capacité de contracter. Les données que vous nous fournissez doivent être exactes et à jour ; si elles cessent de l’être, mettez-les à jour.", "Vous êtes responsable de la confidentialité de vos identifiants et de l’activité réalisée avec votre compte. Si vous soupçonnez un accès non autorisé, prévenez-nous immédiatement et changez votre mot de passe. Nous proposons la vérification en deux étapes et vous recommandons de l’activer.", "Un compte est personnel et incessible. Vous ne pouvez pas le céder, le revendre ni partager l’accès avec des tiers extérieurs à votre organisation."]}, {"h": "Prix, paiements et taxes", "p": ["Les prix sont affichés dans la devise que vous avez activée, avec les taxes et les frais de port détaillés avant confirmation. Le montant débité est celui indiqué dans ce récapitulatif.", "Les paiements sont traités par des prestataires spécialisés (Stripe, PayPal) ou avec le solde de votre portefeuille. Nous ne conservons pas les données complètes de votre carte.", "Les prix peuvent changer à tout moment, mais jamais rétroactivement : une commande déjà confirmée conserve le prix auquel elle a été confirmée. Les abonnements se renouvellent selon la période souscrite jusqu’à ce que vous les résiliiez.", "Les droits de douane et taxes à l’importation applicables à la destination sont calculés et affichés avant le paiement. Si la destination exige des formalités supplémentaires à la charge du destinataire, nous vous l’indiquerons."]}, {"h": "Commandes, expéditions et douanes", "p": ["Une commande est conclue lorsque nous la confirmons, pas avant. Nous pouvons refuser ou annuler une commande —en remboursant intégralement ce qui a été débité— si le produit n’est plus disponible, en cas d’erreur manifeste de prix, si la destination n’est pas desservie ou si nous détectons une utilisation frauduleuse.", "Les délais de livraison affichés sont des estimations fondées sur les informations du transporteur, non des engagements de date ferme, sauf mention expresse contraire.", "Les envois internationaux sont soumis aux contrôles douaniers du pays de destination. Pour que le colis arrive, le transporteur et les autorités reçoivent les données du destinataire et de la marchandise, comme détaillé dans la politique de confidentialité.", "Certains produits ne peuvent pas être expédiés vers certaines destinations en raison de restrictions légales ou du transporteur. La plateforme ne permet pas de finaliser ces commandes."]}, {"h": "Si vous êtes consommateur : vos droits", "p": ["Vous disposez d’un droit de rétractation de QUATORZE (14) jours calendaires à compter de la réception du produit, sans avoir à vous justifier et sans pénalité. Vous pouvez nous le signifier par tout moyen non équivoque, y compris un e-mail à support@nx036.com. Les modalités et les exceptions légales figurent dans notre politique de rétractation.", "Les produits bénéficient de la garantie légale de conformité de TROIS (3) ans à compter de la livraison, en vertu du droit espagnol. Si le produit n’est pas conforme, vous avez droit à sa réparation ou à son remplacement et, le cas échéant, à une réduction du prix ou à la résolution du contrat. Pendant les deux premières années, le défaut est présumé exister dès la livraison : vous n’avez pas à le prouver.", "Aucune clause de ces conditions ne limite, n’exclut ni ne conditionne ces droits. Si l’une pouvait être interprétée en ce sens, elle sera réputée non écrite en ce qui vous concerne.", "Si quelque chose n’a pas été résolu à votre satisfaction, vous pouvez vous adresser à un organisme de règlement extrajudiciaire des litiges (REL) agréé, au réseau des Centres européens des consommateurs (ECC-Net) si vous achetez depuis un autre pays de l’Union, ou aux autorités de consommation de votre pays de résidence."]}, {"h": "Si vous êtes entreprise ou revendeur : vos obligations", "p": ["Lorsque vous revendez à vos propres clients, C’EST VOUS le vendeur à leur égard. Il vous appartient de les informer conformément à la loi applicable, d’émettre la facture, de traiter leur rétractation et leur garantie légale, et de remplir les obligations fiscales de cette vente.", "Vous vous engagez à décrire les produits de manière véridique et à ne pas leur attribuer des caractéristiques, certifications ou origines qu’ils n’ont pas, ainsi qu’à respecter les droits de marque et de propriété intellectuelle de tiers dans vos supports de vente.", "GARANTIE D’INDEMNISATION. Vous nous garantirez —nous, notre personnel et nos fournisseurs— contre toute réclamation, sanction, dommage ou frais, y compris les honoraires raisonnables de défense juridique, résultant de votre manquement à ces conditions, à la réglementation applicable à votre activité, ou de la relation entre vous et vos clients finaux. Cette obligation survit à la fin du contrat.", "Si vous intégrez la plateforme via notre API ou nos connecteurs, vous respecterez les limites d’utilisation publiées et ne l’emploierez pas pour répliquer le catalogue à des fins étrangères à la revente convenue."]}, {"h": "Que se passe-t-il si quelque chose ne va pas", "p": ["Si la commande n’arrive pas, arrive endommagée, incomplète ou ne correspond pas à ce qui a été commandé, signalez-le nous depuis votre compte ou en écrivant à support@nx036.com, en indiquant le numéro de commande. Plus tôt nous le savons, plus tôt nous pouvons réclamer auprès du transporteur, qui a ses propres délais.", "Nous ouvrirons un incident et vous informerons de son avancement. Selon le cas, la solution sera la réexpédition du produit, son remplacement ou le remboursement de ce que vous avez payé ; lorsque la responsabilité incombe au transporteur, nous gérerons la réclamation avec lui.", "Les remboursements sont effectués sur le même moyen de paiement que celui utilisé, sauf accord contraire. Le délai dépend de votre établissement, pas de nous, une fois l’ordre émis.", "Si le problème est une interruption du service ou une erreur de la plateforme, signalez-le également : les incidents techniques sont aussi enregistrés et traités."]}, {"h": "Notre responsabilité", "p": ["Nous répondons de la bonne exécution des obligations que nous assumons dans ces conditions, conformément à la loi applicable.", "RIEN DANS CE CONTRAT N’EXCLUT NI NE LIMITE notre responsabilité en cas de dol, de faute lourde, de dommages corporels, de responsabilité du fait des produits défectueux, ni toute autre que la loi ne permet pas d’exclure. Toute limitation de cette section s’entend sous cette réserve.", "Envers les CLIENTS QUI NE SONT PAS CONSOMMATEURS et dans toute la mesure permise par la loi : nous ne répondons pas du manque à gagner, de la perte d’exploitation, de clientèle, de données ou d’opportunité, ni des dommages indirects ou consécutifs ; et notre responsabilité totale cumulée pour toute réclamation est limitée au montant que vous nous avez versé au cours des douze mois précédant le fait générateur.", "Nous ne répondons pas de l’usage que vous faites de la plateforme en violation de ces conditions ou de la loi, ni des obligations qui vous incombent envers vos propres clients."]}, {"h": "Disponibilité du service", "p": ["Nous œuvrons pour que la plateforme soit disponible en continu, mais nous ne garantissons pas une disponibilité ininterrompue ni exempte d’erreurs. Des arrêts peuvent survenir pour maintenance, mises à jour ou causes indépendantes de notre volonté.", "Lorsque la maintenance est programmée et affectera le service, nous nous efforcerons de prévenir dans un délai raisonnable et de l’effectuer aux heures de faible affluence.", "Nous pouvons modifier, suspendre ou retirer des fonctionnalités. Si une modification vous porte un préjudice substantiel et que vous avez un abonnement en cours, vous pourrez le résilier avec remboursement de la partie non consommée."]}, {"h": "Utilisation acceptable et suspension", "p": ["Vous ne pouvez pas utiliser la plateforme à des fins illicites, pour porter atteinte aux droits de tiers, pour introduire du code malveillant, pour tenter d’accéder à des données ou comptes d’autrui, ni pour procéder à de l’ingénierie inverse, à une extraction massive de données ou à tout usage qui dégrade le service.", "Nous pouvons suspendre ou fermer un compte qui enfreint ces conditions ou la loi, ou en cas de soupçon fondé de fraude. Sauf si l’urgence ou la loi l’empêche, nous vous préviendrons au préalable en indiquant le motif, et vous pourrez faire valoir vos observations.", "La suspension ne vous libère pas des sommes déjà dues et n’affecte pas les commandes en cours, qui seront exécutées ou remboursées selon le cas."]}, {"h": "Propriété intellectuelle", "p": ["La plateforme, son logiciel, son design, ses marques et les contenus que nous élaborons nous appartiennent ou appartiennent à ceux qui nous en ont concédé l’usage. Votre compte vous donne le droit d’utiliser le service, pas de vous approprier l’un de ces éléments.", "Les images et descriptions du catalogue sont mises à votre disposition pour vendre les produits acquis via la plateforme. Cet usage ne fait pas de vous le titulaire d’un quelconque droit sur elles et ne vous autorise pas à les employer à d’autres fins.", "Les contenus que vous apportez restent les vôtres ; en les publiant, vous nous concédez la licence strictement nécessaire à la fourniture du service."]}, {"h": "Force majeure", "p": ["Nous ne répondrons pas de l’inexécution ou du retard résultant de circonstances échappant à notre contrôle raisonnable : catastrophes naturelles, conflits armés, troubles civils, épidémies, grèves étrangères à notre personnel, décisions des autorités, fermetures de frontières ou de douanes, défaillances généralisées des réseaux de télécommunications ou de l’alimentation électrique.", "Si la circonstance se prolonge au-delà de trente jours, chacune des parties pourra résoudre le contrat concerné, avec remboursement de ce qui a été payé et non fourni. Cette clause ne couvre pas la simple difficulté économique ni le renchérissement des coûts."]}, {"h": "Durée, clôture du compte et résiliation", "p": ["Le contrat est en vigueur tant que vous conservez votre compte. Vous pouvez le clôturer quand vous le souhaitez depuis votre profil, sans justification et sans pénalité.", "La clôture n’annule pas à elle seule un abonnement en cours ni les commandes déjà confirmées. Nous conservons les documents fiscaux le temps exigé par la loi, comme détaillé dans la politique de confidentialité.", "Les clauses qui, par leur nature, doivent survivre à la fin du contrat —garantie d’indemnisation, responsabilité, propriété intellectuelle, loi applicable et juridiction— resteront en vigueur."]}, {"h": "Modifications de ces conditions", "p": ["Nous pouvons modifier ces conditions pour les adapter à des changements légaux, techniques ou de service. Nous publierons la nouvelle version avec sa date et préviendrons par e-mail tous les comptes actifs.", "Si vous n’acceptez pas la nouvelle version, vous pouvez clôturer votre compte avant qu’elle ne s’applique. Les commandes confirmées auparavant sont régies par la version en vigueur au moment de leur confirmation."]}, {"h": "Nullité partielle", "p": ["Si une autorité compétente déclare une clause nulle ou inapplicable, cette clause sera remplacée par une clause valable d’effet équivalent dans la mesure permise par la loi, et le reste du contrat demeurera pleinement en vigueur."]}, {"h": "Loi applicable et règlement des litiges", "p": ["Ces conditions sont régies par la loi du pays où nous sommes domiciliés, sans préjudice des règles impératives applicables.", "Si vous êtes CONSOMMATEUR, ce choix ne vous prive pas de la protection que vous accordent les règles impératives de votre pays de résidence habituelle, et vous pourrez agir et être attrait devant les tribunaux de votre domicile.", "Si vous N’ÊTES PAS consommateur, les parties se soumettent aux tribunaux de notre domicile, en renonçant à toute autre juridiction qui pourrait leur revenir.", "Avant de saisir les tribunaux, nous vous demandons de nous écrire à support@nx036.com : la plupart des problèmes se règlent ainsi, et plus vite."]}]}','2026-08-15'),
('terms','de','Allgemeine Nutzungsbedingungen','{"intro": "Diese Bedingungen regeln den Zugang zur Plattform NX036 und ihre Nutzung und bilden einen Vertrag zwischen dir und uns. Lies sie: Mit der Erstellung eines Kontos erklärst du, sie gelesen und akzeptiert zu haben. Sie sind so geschrieben, dass man sie überprüfen kann — wenn hier etwas nicht dem entspricht, was wir tatsächlich tun, ist das unser Fehler und wir wollen davon wissen.", "sections": [{"h": "Wer wir sind", "p": ["Betreiber der Plattform ist Jesús Enrique Finol Finol, Steuernummer PENDIENTE-NIF, mit Anschrift Calle Castelví 7, 1D, 50004 Zaragoza, España, tätig unter dem Handelsnamen NX036. Du kannst uns jederzeit unter support@nx036.com schreiben."]}, {"h": "Für wen diese Bedingungen gelten", "p": ["Die Plattform wird von zwei sehr unterschiedlichen Kundengruppen genutzt, für die nicht dasselbe gelten kann; deshalb unterscheiden diese Bedingungen ausdrücklich zwischen beiden:", "Du bist VERBRAUCHER, wenn du für deinen persönlichen Gebrauch kaufst, außerhalb jeder beruflichen oder gewerblichen Tätigkeit. Das Verbraucherrecht gilt für dich uneingeschränkt, und nichts in diesem Vertrag beschränkt oder ersetzt es. Die Abschnitte, die dir diese Rechte zuerkennen, gehen jedem anderen vor, der ihnen widersprechen könnte.", "Du bist UNTERNEHMEN ODER WIEDERVERKÄUFER, wenn du im Rahmen einer beruflichen Tätigkeit handelst; dazu zählt, wer zum Weiterverkauf kauft, die Plattform in seinen eigenen Shop einbindet oder unsere API nutzt. In diesem Fall gelten die Verbraucherrechte nicht für dich —weil du rechtlich kein Verbraucher bist— und die besonderen Pflichten des entsprechenden Abschnitts schon.", "Wenn du unsicher bist, welcher Kategorie du angehörst, schreib uns vor Vertragsschluss. Bei Auslegungsstreit und wenn Anhaltspunkte für beide Eigenschaften vorliegen, gilt die Verbraucherregelung als die schützendere."]}, {"h": "Was die Plattform ist und was nicht", "p": ["NX036 ist eine Technologieplattform, die Zugang zu einem Katalog von Lieferantenprodukten bietet, Bestellungen verwaltet und deren Versand und Zollabfertigung koordiniert.", "Wird die Bestellung von einem Verbraucher in unserem eigenen Shop aufgegeben, handeln wir als Verkäufer und haften ihm gegenüber als solcher, mit allem, was das bedeutet.", "Nutzt ein Wiederverkäufer die Plattform, um Bestellungen SEINER Kunden zu erfüllen, ist der Verkauf an diese Endkunden seiner, nicht unserer: Wir verkaufen an ihn und erbringen die Logistikleistung. Er ist es, der mit seinem Käufer den Vertrag schließt, seine Rechnung stellt, den Kundendienst übernimmt und für die gesetzlichen Pflichten dieses Verkaufs einsteht.", "Wir stellen die Produkte nicht her. Wo das Gesetz es verlangt, handeln wir als Wirtschaftsakteur in der Union; diese Angabe steht auf der Seite jedes Produkts und auf der Rechnung."]}, {"h": "Dein Konto", "p": ["Um die Plattform zu nutzen, brauchst du ein Konto, musst volljährig und geschäftsfähig sein. Die Daten, die du uns gibst, müssen wahr und aktuell sein; wenn sie es nicht mehr sind, aktualisiere sie.", "Du bist für die Vertraulichkeit deiner Zugangsdaten und für die mit deinem Konto ausgeführten Handlungen verantwortlich. Wenn du einen unbefugten Zugriff vermutest, sag uns sofort Bescheid und ändere dein Passwort. Wir bieten die Zwei-Schritt-Verifizierung an und empfehlen, sie zu aktivieren.", "Ein Konto ist persönlich und nicht übertragbar. Du darfst es weder abtreten noch weiterverkaufen noch den Zugang mit Dritten außerhalb deiner Organisation teilen."]}, {"h": "Preise, Zahlungen und Steuern", "p": ["Die Preise werden in deiner aktiven Währung angezeigt, mit Steuern und Versandkosten aufgeschlüsselt vor der Bestätigung. Berechnet wird der Betrag, der in dieser Übersicht steht.", "Zahlungen werden über spezialisierte Anbieter (Stripe, PayPal) oder mit deinem Guthaben abgewickelt. Wir speichern keine vollständigen Kartendaten.", "Preise können sich jederzeit ändern, aber nie rückwirkend: Eine bereits bestätigte Bestellung behält den Preis, zu dem sie bestätigt wurde. Abonnements verlängern sich um den gebuchten Zeitraum, bis du sie kündigst.", "Zölle und Einfuhrsteuern des Bestimmungslandes werden vor der Zahlung berechnet und angezeigt. Verlangt das Zielland zusätzliche Formalitäten vom Empfänger, teilen wir dir das mit."]}, {"h": "Bestellungen, Versand und Zoll", "p": ["Eine Bestellung kommt zustande, wenn wir sie bestätigen, nicht vorher. Wir können eine Bestellung ablehnen oder stornieren —unter vollständiger Rückerstattung des Berechneten—, wenn das Produkt nicht mehr verfügbar ist, bei einem offensichtlichen Preisfehler, wenn das Ziel nicht bedient werden kann oder wenn wir eine missbräuchliche Nutzung feststellen.", "Die angezeigten Lieferzeiten sind Schätzungen auf Grundlage der Angaben des Transportunternehmens, keine verbindlichen Termine, sofern nicht ausdrücklich anders angegeben.", "Internationale Sendungen unterliegen den Zollkontrollen des Bestimmungslandes. Damit das Paket ankommt, erhalten das Transportunternehmen und die Behörden die Daten des Empfängers und der Ware, wie in der Datenschutzerklärung dargelegt.", "Manche Produkte können wegen gesetzlicher Beschränkungen oder Vorgaben des Transportunternehmens nicht an bestimmte Ziele versandt werden. Die Plattform lässt solche Bestellungen nicht zu."]}, {"h": "Wenn du Verbraucher bist: deine Rechte", "p": ["Du hast das Recht, innerhalb von VIERZEHN (14) Kalendertagen ab Erhalt der Ware ohne Angabe von Gründen und ohne Strafe vom Vertrag zurückzutreten. Du kannst uns das auf jedem eindeutigen Weg mitteilen, auch per E-Mail an support@nx036.com. Einzelheiten und die gesetzlichen Ausnahmen stehen in unserer Widerrufsbelehrung.", "Für die Produkte gilt die gesetzliche Gewährleistung von DREI (3) Jahren ab Lieferung nach spanischem Recht. Ist die Ware nicht vertragsgemäß, hast du Anspruch auf Nachbesserung oder Ersatzlieferung und, wo einschlägig, auf Minderung oder Rücktritt vom Vertrag. In den ersten zwei Jahren wird vermutet, dass der Mangel schon bei Lieferung vorlag; du musst ihn also nicht nachweisen.", "Keine Klausel dieser Bedingungen beschränkt, schließt aus oder bedingt diese Rechte. Sollte eine in diesem Sinne ausgelegt werden können, gilt sie dir gegenüber als nicht geschrieben.", "Wurde etwas nicht zu deiner Zufriedenheit gelöst, kannst du dich an eine anerkannte Stelle zur alternativen Streitbeilegung (AS-Stelle), an das Netz der Europäischen Verbraucherzentren (ECC-Net) bei Käufen aus einem anderen EU-Land oder an die Verbraucherbehörden deines Wohnsitzlandes wenden."]}, {"h": "Wenn du Unternehmen oder Wiederverkäufer bist: deine Pflichten", "p": ["Wenn du an deine eigenen Kunden weiterverkaufst, bist DU ihnen gegenüber der Verkäufer. Es obliegt dir, sie nach geltendem Recht zu informieren, die Rechnung zu stellen, ihren Widerruf und ihre gesetzliche Gewährleistung zu bearbeiten und die steuerlichen Pflichten dieses Verkaufs zu erfüllen.", "Du verpflichtest dich, die Produkte wahrheitsgemäß zu beschreiben und ihnen keine Eigenschaften, Zertifizierungen oder Herkünfte zuzuschreiben, die sie nicht haben, sowie in deinen Verkaufsunterlagen Marken- und Urheberrechte Dritter zu achten.", "FREISTELLUNG. Du stellst uns —uns, unsere Mitarbeitenden und unsere Lieferanten— von jeder Forderung, Sanktion, jedem Schaden oder Aufwand frei, einschließlich angemessener Kosten der Rechtsverteidigung, die auf deinem Verstoß gegen diese Bedingungen, gegen das für deine Tätigkeit geltende Recht oder auf dem Verhältnis zwischen dir und deinen Endkunden beruhen. Diese Pflicht besteht nach Vertragsende fort.", "Bindest du die Plattform über unsere API oder unsere Konnektoren ein, hältst du die veröffentlichten Nutzungsgrenzen ein und verwendest sie nicht, um den Katalog zu vervielfältigen zu anderen Zwecken als dem vereinbarten Weiterverkauf."]}, {"h": "Was passiert, wenn etwas schiefgeht", "p": ["Kommt die Bestellung nicht an, beschädigt an, unvollständig an oder entspricht sie nicht dem Bestellten, melde es uns über dein Konto oder per E-Mail an support@nx036.com unter Angabe der Bestellnummer. Je früher wir davon erfahren, desto eher können wir beim Transportunternehmen reklamieren, das eigene Fristen hat.", "Wir eröffnen einen Vorgang und halten dich über den Verlauf auf dem Laufenden. Je nach Fall ist die Lösung ein erneuter Versand, ein Ersatz oder die Erstattung des Gezahlten; liegt die Verantwortung beim Transportunternehmen, führen wir die Reklamation mit ihm.", "Erstattungen erfolgen auf dasselbe Zahlungsmittel, das du verwendet hast, sofern nichts anderes vereinbart ist. Die Dauer hängt nach Auslösung der Anweisung von deinem Institut ab, nicht von uns.", "Ist das Problem eine Betriebsunterbrechung oder ein Fehler der Plattform, melde es genauso: Auch technische Vorfälle werden erfasst und beantwortet."]}, {"h": "Unsere Haftung", "p": ["Wir haften für die ordnungsgemäße Erfüllung der Pflichten, die wir in diesen Bedingungen übernehmen, nach Maßgabe des anwendbaren Rechts.", "NICHTS IN DIESEM VERTRAG SCHLIESST UNSERE HAFTUNG AUS ODER BESCHRÄNKT SIE bei Vorsatz, grober Fahrlässigkeit, Personenschäden, Haftung für fehlerhafte Produkte oder bei jeder anderen Haftung, deren Ausschluss das Gesetz nicht erlaubt. Jede Beschränkung dieses Abschnitts steht unter diesem Vorbehalt.", "Gegenüber KUNDEN, DIE KEINE VERBRAUCHER SIND, und im größtmöglichen gesetzlich zulässigen Umfang: Wir haften nicht für entgangenen Gewinn, Geschäfts-, Kundschafts-, Daten- oder Chancenverlust noch für mittelbare oder Folgeschäden; und unsere gesamte Haftung für jede Forderung ist auf den Betrag begrenzt, den du uns in den zwölf Monaten vor dem auslösenden Ereignis gezahlt hast.", "Wir haften nicht für deine Nutzung der Plattform entgegen diesen Bedingungen oder dem Gesetz noch für die Pflichten, die dir gegenüber deinen eigenen Kunden obliegen."]}, {"h": "Verfügbarkeit des Dienstes", "p": ["Wir arbeiten daran, dass die Plattform durchgehend verfügbar ist, garantieren aber keine unterbrechungs- oder fehlerfreie Verfügbarkeit. Es kann zu Ausfällen durch Wartung, Aktualisierungen oder Ursachen außerhalb unseres Einflusses kommen.", "Ist eine Wartung geplant und wird sie den Dienst beeinträchtigen, werden wir uns bemühen, angemessen vorher zu informieren und sie in Zeiten geringer Nutzung durchzuführen.", "Wir können Funktionen ändern, aussetzen oder einstellen. Beeinträchtigt dich eine Änderung wesentlich und hast du ein laufendes Abonnement, kannst du es unter Erstattung des nicht verbrauchten Teils kündigen."]}, {"h": "Zulässige Nutzung und Sperrung", "p": ["Du darfst die Plattform nicht für rechtswidrige Zwecke nutzen, nicht zur Verletzung von Rechten Dritter, nicht zum Einschleusen von Schadcode, nicht zum Versuch, auf fremde Daten oder Konten zuzugreifen, und nicht für Reverse Engineering, massenhaftes Auslesen von Daten oder jede Nutzung, die den Dienst beeinträchtigt.", "Wir können ein Konto sperren oder schließen, das gegen diese Bedingungen oder das Gesetz verstößt, oder bei begründetem Betrugsverdacht. Sofern Dringlichkeit oder Gesetz nicht entgegenstehen, informieren wir dich vorher unter Angabe des Grundes, und du kannst Stellung nehmen.", "Die Sperrung befreit dich nicht von bereits fälligen Beträgen und berührt laufende Bestellungen nicht, die je nach Fall ausgeführt oder erstattet werden."]}, {"h": "Geistiges Eigentum", "p": ["Die Plattform, ihre Software, ihr Design, ihre Marken und die von uns erstellten Inhalte gehören uns oder denen, die uns die Nutzung lizenziert haben. Dein Konto gibt dir das Recht, den Dienst zu nutzen, nicht, dir eines dieser Elemente anzueignen.", "Bilder und Beschreibungen des Katalogs werden dir zur Verfügung gestellt, um die über die Plattform erworbenen Produkte zu verkaufen. Diese Nutzung macht dich nicht zum Inhaber irgendeines Rechts daran und berechtigt dich nicht, sie zu anderen Zwecken zu verwenden.", "Von dir eingebrachte Inhalte bleiben deine; mit ihrer Veröffentlichung räumst du uns die zur Erbringung des Dienstes unbedingt erforderliche Lizenz ein."]}, {"h": "Höhere Gewalt", "p": ["Wir haften nicht für Nichterfüllung oder Verzug aufgrund von Umständen außerhalb unseres zumutbaren Einflussbereichs: Naturkatastrophen, bewaffnete Konflikte, Unruhen, Epidemien, Streiks außerhalb unserer Belegschaft, behördliche Entscheidungen, Grenz- oder Zollschließungen, großflächige Ausfälle von Telekommunikationsnetzen oder der Stromversorgung.", "Dauert der Umstand länger als dreißig Tage, kann jede Partei den betroffenen Vertrag beenden, unter Erstattung des Gezahlten und nicht Erbrachten. Diese Klausel erfasst weder bloße wirtschaftliche Schwierigkeiten noch Kostensteigerungen."]}, {"h": "Laufzeit, Kontoschließung und Kündigung", "p": ["Der Vertrag gilt, solange du dein Konto behältst. Du kannst es jederzeit in deinem Profil schließen, ohne Begründung und ohne Strafe.", "Die Schließung kündigt für sich genommen weder ein laufendes Abonnement noch bereits bestätigte Bestellungen. Steuerunterlagen bewahren wir so lange auf, wie das Gesetz es verlangt, wie in der Datenschutzerklärung dargelegt.", "Klauseln, die ihrer Natur nach das Vertragsende überdauern müssen —Freistellung, Haftung, geistiges Eigentum, anwendbares Recht und Gerichtsstand—, bleiben in Kraft."]}, {"h": "Änderungen dieser Bedingungen", "p": ["Wir können diese Bedingungen ändern, um sie an rechtliche, technische oder dienstbezogene Änderungen anzupassen. Wir veröffentlichen die neue Fassung mit ihrem Datum und informieren alle aktiven Konten per E-Mail.", "Bist du mit der neuen Fassung nicht einverstanden, kannst du dein Konto schließen, bevor sie greift. Zuvor bestätigte Bestellungen richten sich nach der bei ihrer Bestätigung geltenden Fassung."]}, {"h": "Salvatorische Klausel", "p": ["Erklärt eine zuständige Stelle eine Klausel für nichtig oder undurchsetzbar, wird sie im gesetzlich zulässigen Umfang durch eine wirksame Klausel gleicher Wirkung ersetzt; der übrige Vertrag bleibt vollumfänglich in Kraft."]}, {"h": "Anwendbares Recht und Streitbeilegung", "p": ["Diese Bedingungen unterliegen dem Recht des Landes, in dem wir unseren Sitz haben, unbeschadet zwingender Vorschriften, die anwendbar sein können.", "Bist du VERBRAUCHER, nimmt dir diese Wahl nicht den Schutz, den dir die zwingenden Vorschriften deines gewöhnlichen Aufenthaltslandes gewähren, und du kannst vor den Gerichten deines Wohnsitzes klagen und verklagt werden.", "Bist du KEIN Verbraucher, unterwerfen sich die Parteien den Gerichten unseres Sitzes und verzichten auf jeden anderen Gerichtsstand, der ihnen zustehen könnte.", "Bevor du vor Gericht gehst, schreib uns bitte an support@nx036.com: Die meisten Probleme lassen sich so lösen, und schneller."]}]}','2026-08-15'),
('terms','it','Termini e condizioni d’uso','{"intro": "Questi termini regolano l’accesso alla piattaforma NX036 e il suo utilizzo e formano un contratto tra te e noi. Leggili: creando un account dichiari di averli letti e accettati. Sono scritti per poter essere verificati — se qualcosa qui non corrisponde a ciò che facciamo, è un nostro errore e vogliamo saperlo.", "sections": [{"h": "Chi siamo", "p": ["Il titolare della piattaforma è Jesús Enrique Finol Finol, codice fiscale PENDIENTE-NIF, con domicilio in Calle Castelví 7, 1D, 50004 Zaragoza, España, che opera con il nome commerciale NX036. Puoi scriverci in qualsiasi momento a support@nx036.com."]}, {"h": "A chi si applicano questi termini", "p": ["La piattaforma è usata da due tipi di clienti molto diversi e non si può applicare loro lo stesso trattamento, perciò questi termini distinguono espressamente tra i due:", "Sei CONSUMATORE se acquisti per uso personale, al di fuori di qualsiasi attività professionale o imprenditoriale. La normativa a tutela dei consumatori ti si applica integralmente, e nulla in questo contratto la limita o la sostituisce. Le sezioni che ti riconoscono tali diritti prevalgono su qualsiasi altra che possa contraddirle.", "Sei IMPRESA O RIVENDITORE se agisci nell’ambito di un’attività professionale, il che include chi acquista per rivendere, integra la piattaforma nel proprio negozio o usa la nostra API. In tal caso i diritti dei consumatori non ti si applicano —perché giuridicamente non sei consumatore— e si applicano invece gli obblighi specifici della sezione corrispondente.", "Se hai dubbi sulla categoria in cui rientri, scrivici prima di contrattare. In caso di conflitto interpretativo, e in presenza di indizi di entrambe le condizioni, si applicherà il regime del consumatore in quanto più protettivo."]}, {"h": "Che cos’è la piattaforma e che cosa non è", "p": ["NX036 è una piattaforma tecnologica che dà accesso a un catalogo di prodotti di fornitori, gestisce gli ordini e ne coordina la spedizione e lo sdoganamento.", "Quando l’ordine è effettuato da un consumatore sul nostro negozio, agiamo come venditore e rispondiamo come tali nei suoi confronti, con tutto ciò che ne consegue.", "Quando un rivenditore usa la piattaforma per servire gli ordini dei SUOI clienti, la vendita a quei clienti finali è sua, non nostra: noi vendiamo a lui e gli forniamo il servizio logistico. È lui che contratta con il proprio acquirente, emette la propria fattura, cura il post-vendita e risponde degli obblighi di legge di quella vendita.", "Non fabbrichiamo i prodotti. Quando la normativa lo richiede, agiamo come operatore economico nell’Unione e tale informazione compare nella scheda di ogni prodotto e in fattura."]}, {"h": "Il tuo account", "p": ["Per usare la piattaforma ti serve un account, devi essere maggiorenne e avere la capacità di contrattare. I dati che ci fornisci devono essere veritieri e aggiornati; se smettono di esserlo, aggiornali.", "Sei responsabile della riservatezza delle tue credenziali e dell’attività svolta con il tuo account. Se sospetti un accesso non autorizzato, avvisaci subito e cambia la password. Offriamo la verifica in due passaggi e ti consigliamo di attivarla.", "Un account è personale e non trasferibile. Non puoi cederlo, rivenderlo né condividere l’accesso con terzi estranei alla tua organizzazione."]}, {"h": "Prezzi, pagamenti e imposte", "p": ["I prezzi sono mostrati nella valuta che hai attiva, con imposte e costi di spedizione dettagliati prima della conferma. L’importo addebitato è quello indicato in quel riepilogo.", "I pagamenti sono elaborati tramite fornitori specializzati (Stripe, PayPal) o con il saldo del tuo portafoglio. Non conserviamo i dati completi della tua carta.", "I prezzi possono cambiare in qualsiasi momento, ma mai retroattivamente: un ordine già confermato mantiene il prezzo al quale è stato confermato. Gli abbonamenti si rinnovano secondo il periodo sottoscritto finché non li disdici.", "I dazi e le imposte all’importazione applicabili alla destinazione sono calcolati e mostrati prima del pagamento. Se la destinazione richiede formalità aggiuntive a carico del destinatario, te lo indicheremo."]}, {"h": "Ordini, spedizioni e dogana", "p": ["Un ordine si perfeziona quando lo confermiamo, non prima. Possiamo rifiutare o annullare un ordine —rimborsando integralmente quanto addebitato— se il prodotto non è più disponibile, in caso di errore manifesto di prezzo, se la destinazione non è servibile o se rileviamo un uso fraudolento.", "I tempi di consegna che mostriamo sono stime basate sulle informazioni del vettore, non impegni su una data certa, salvo diversa indicazione espressa.", "Le spedizioni internazionali sono soggette ai controlli doganali del Paese di destinazione. Perché il pacco arrivi, il vettore e le autorità ricevono i dati del destinatario e della merce, come dettagliato nell’informativa sulla privacy.", "Alcuni prodotti non possono essere spediti verso determinate destinazioni per restrizioni di legge o del vettore. La piattaforma non consente di completare tali ordini."]}, {"h": "Se sei consumatore: i tuoi diritti", "p": ["Hai diritto di recedere dal contratto entro QUATTORDICI (14) giorni di calendario dal ricevimento del prodotto, senza doverlo motivare e senza penalità. Puoi comunicarcelo con qualsiasi mezzo inequivoco, incluso un messaggio a support@nx036.com. I dettagli e le eccezioni di legge sono nella nostra politica di recesso.", "I prodotti godono della garanzia legale di conformità di TRE (3) anni dalla consegna, secondo la legge spagnola. Se il prodotto non è conforme, hai diritto alla riparazione o alla sostituzione e, se del caso, alla riduzione del prezzo o alla risoluzione del contratto. Nei primi due anni si presume che il difetto esistesse già alla consegna, quindi non devi dimostrarlo.", "Nessuna clausola di questi termini limita, esclude o condiziona tali diritti. Se una potesse essere interpretata in tal senso, si avrà per non apposta per quanto ti riguarda.", "Se qualcosa non è stato risolto in modo soddisfacente, puoi rivolgerti a un organismo accreditato di risoluzione alternativa delle controversie (ADR), alla rete dei Centri europei dei consumatori (ECC-Net) se acquisti da un altro Paese dell’Unione, o alle autorità di tutela dei consumatori del tuo Paese di residenza."]}, {"h": "Se sei impresa o rivenditore: i tuoi obblighi", "p": ["Quando rivendi ai tuoi clienti, SEI TU il venditore nei loro confronti. Spetta a te informarli secondo la normativa applicabile, emettere la fattura, gestire il loro recesso e la garanzia legale, e adempiere agli obblighi fiscali di quella vendita.", "Ti impegni a descrivere i prodotti in modo veritiero e a non attribuire loro caratteristiche, certificazioni o origini che non hanno, nonché a rispettare i diritti di marchio e di proprietà intellettuale di terzi nei tuoi materiali di vendita.", "MANLEVA. Ci terrai indenni —noi, il nostro personale e i nostri fornitori— da qualsiasi pretesa, sanzione, danno o spesa, comprese le ragionevoli spese di difesa legale, derivanti dal tuo inadempimento di questi termini, della normativa applicabile alla tua attività, o dal rapporto tra te e i tuoi clienti finali. Tale obbligo sopravvive alla cessazione del contratto.", "Se integri la piattaforma tramite la nostra API o i nostri connettori, rispetterai i limiti d’uso pubblicati e non la userai per replicare il catalogo per finalità estranee alla rivendita pattuita."]}, {"h": "Che cosa succede se qualcosa va storto", "p": ["Se l’ordine non arriva, arriva danneggiato, arriva incompleto o non corrisponde a quanto ordinato, segnalacelo dal tuo account o scrivendo a support@nx036.com, indicando il numero d’ordine. Prima lo sappiamo, prima possiamo reclamare al vettore, che ha tempi propri.", "Apriremo una segnalazione e ti informeremo del suo andamento. A seconda del caso, la soluzione sarà la rispedizione del prodotto, la sua sostituzione o il rimborso di quanto pagato; quando la responsabilità è del vettore, gestiremo il reclamo con lui.", "I rimborsi avvengono sullo stesso mezzo di pagamento che hai usato, salvo diverso accordo. I tempi dipendono dal tuo istituto, non da noi, una volta emesso l’ordine.", "Se il problema è un’interruzione del servizio o un errore della piattaforma, segnalacelo lo stesso: anche gli incidenti tecnici vengono registrati e gestiti."]}, {"h": "La nostra responsabilità", "p": ["Rispondiamo del corretto adempimento degli obblighi che assumiamo in questi termini, secondo la legge applicabile.", "NULLA IN QUESTO CONTRATTO ESCLUDE O LIMITA la nostra responsabilità per dolo, colpa grave, danni alla persona, responsabilità da prodotto difettoso, né alcun’altra che la legge non consenta di escludere. Ogni limitazione di questa sezione si intende soggetta a tale limite.", "Verso CLIENTI CHE NON SONO CONSUMATORI e nella massima misura consentita dalla legge: non rispondiamo del lucro cessante, della perdita di affari, di clientela, di dati o di opportunità, né di danni indiretti o consequenziali; e la nostra responsabilità complessiva per qualsiasi pretesa è limitata all’importo che ci hai corrisposto nei dodici mesi precedenti il fatto che la origina.", "Non rispondiamo dell’uso che fai della piattaforma in violazione di questi termini o della legge, né degli obblighi che spettano a te verso i tuoi clienti."]}, {"h": "Disponibilità del servizio", "p": ["Lavoriamo perché la piattaforma sia disponibile con continuità, ma non garantiamo una disponibilità ininterrotta né esente da errori. Possono verificarsi fermi per manutenzione, aggiornamenti o cause a noi estranee.", "Quando la manutenzione è programmata e inciderà sul servizio, cercheremo di avvisare con ragionevole anticipo e di effettuarla nelle fasce di minor utilizzo.", "Possiamo modificare, sospendere o ritirare funzionalità. Se una modifica ti pregiudica in modo sostanziale e hai un abbonamento in corso, potrai disdirlo con rimborso della parte non fruita."]}, {"h": "Uso accettabile e sospensione", "p": ["Non puoi usare la piattaforma per fini illeciti, per violare diritti di terzi, per introdurre codice dannoso, per tentare di accedere a dati o account altrui, né per effettuare reverse engineering, estrazione massiva di dati o qualsiasi uso che degradi il servizio.", "Possiamo sospendere o chiudere un account che violi questi termini o la legge, o in presenza di fondato sospetto di frode. Salvo che l’urgenza o la legge lo impediscano, ti avviseremo prima indicando il motivo, e potrai far valere le tue ragioni.", "La sospensione non ti libera dagli importi già maturati né incide sugli ordini in corso, che saranno completati o rimborsati a seconda dei casi."]}, {"h": "Proprietà intellettuale", "p": ["La piattaforma, il suo software, il suo design, i suoi marchi e i contenuti che realizziamo sono nostri o di chi ce ne ha concesso l’uso. Il tuo account ti dà il diritto di usare il servizio, non di appropriarti di alcuno di tali elementi.", "Le immagini e le descrizioni del catalogo sono messe a tua disposizione per vendere i prodotti acquistati tramite la piattaforma. Tale uso non ti rende titolare di alcun diritto su di esse né ti autorizza a impiegarle per altri fini.", "I contenuti che apporti restano tuoi; pubblicandoli ci concedi la licenza strettamente necessaria a erogarti il servizio."]}, {"h": "Forza maggiore", "p": ["Non risponderemo dell’inadempimento o del ritardo dovuto a circostanze fuori dal nostro ragionevole controllo: catastrofi naturali, conflitti armati, disordini, epidemie, scioperi estranei al nostro personale, decisioni delle autorità, chiusure di frontiere o dogane, guasti generalizzati delle reti di telecomunicazione o della fornitura elettrica.", "Se la circostanza si protrae oltre trenta giorni, ciascuna parte potrà risolvere il contratto interessato, con rimborso di quanto pagato e non prestato. Questa clausola non copre la mera difficoltà economica né l’aumento dei costi."]}, {"h": "Durata, chiusura dell’account e disdetta", "p": ["Il contratto è in vigore finché mantieni il tuo account. Puoi chiuderlo quando vuoi dal tuo profilo, senza dare spiegazioni e senza penalità.", "La chiusura non annulla di per sé un abbonamento in corso né gli ordini già confermati. Conserviamo la documentazione fiscale per il tempo richiesto dalla legge, come dettagliato nell’informativa sulla privacy.", "Le clausole che per loro natura devono sopravvivere alla cessazione —manleva, responsabilità, proprietà intellettuale, legge applicabile e foro— resteranno in vigore."]}, {"h": "Modifiche a questi termini", "p": ["Possiamo modificare questi termini per adeguarli a cambiamenti normativi, tecnici o del servizio. Pubblicheremo la nuova versione con la sua data e avviseremo via email tutti gli account attivi.", "Se non sei d’accordo con la nuova versione, puoi chiudere il tuo account prima che entri in vigore. Gli ordini confermati in precedenza sono regolati dalla versione vigente al momento della conferma."]}, {"h": "Nullità parziale", "p": ["Se un’autorità competente dichiara nulla o inapplicabile una clausola, questa sarà sostituita da una valida di effetto equivalente nei limiti consentiti dalla legge, e il resto del contratto resterà pienamente in vigore."]}, {"h": "Legge applicabile e risoluzione delle controversie", "p": ["Questi termini sono regolati dalla legge del Paese in cui abbiamo il nostro domicilio, fatte salve le norme imperative eventualmente applicabili.", "Se sei CONSUMATORE, questa scelta non ti priva della tutela accordata dalle norme imperative del tuo Paese di residenza abituale, e potrai agire ed essere convenuto davanti ai tribunali del tuo domicilio.", "Se NON sei consumatore, le parti si sottopongono ai tribunali del nostro domicilio, con rinuncia a ogni altro foro che potesse loro competere.", "Prima di rivolgerti ai tribunali ti chiediamo di scriverci a support@nx036.com: la maggior parte dei problemi si risolve così, e più in fretta."]}]}','2026-08-15'),
('terms','nl','Algemene gebruiksvoorwaarden','{"intro": "Deze voorwaarden regelen de toegang tot en het gebruik van het NX036-platform en vormen een overeenkomst tussen jou en ons. Lees ze: door een account aan te maken verklaar je ze gelezen en aanvaard te hebben. Ze zijn zo geschreven dat je ze kunt controleren — klopt hier iets niet met wat we werkelijk doen, dan is dat onze fout en willen we het horen.", "sections": [{"h": "Wie we zijn", "p": ["Het platform wordt geëxploiteerd door Jesús Enrique Finol Finol, fiscaal nummer PENDIENTE-NIF, gevestigd te Calle Castelví 7, 1D, 50004 Zaragoza, España, handelend onder de naam NX036. Je kunt ons altijd schrijven op support@nx036.com."]}, {"h": "Voor wie deze voorwaarden gelden", "p": ["Het platform wordt gebruikt door twee heel verschillende soorten klanten, en voor hen kan niet hetzelfde gelden; daarom maken deze voorwaarden uitdrukkelijk onderscheid:", "Je bent CONSUMENT als je koopt voor persoonlijk gebruik, buiten enige beroeps- of bedrijfsmatige activiteit. Het consumentenrecht is volledig op jou van toepassing, en niets in deze overeenkomst beperkt of vervangt het. De secties die je die rechten toekennen gaan voor op elke andere die ze zou kunnen tegenspreken.", "Je bent ONDERNEMING OF WEDERVERKOPER als je handelt in het kader van een beroepsactiviteit, waaronder wie koopt om door te verkopen, het platform in de eigen winkel integreert of onze API gebruikt. In dat geval gelden de consumentenrechten niet voor jou —omdat je juridisch geen consument bent— en gelden wel de specifieke verplichtingen van de betreffende sectie.", "Twijfel je in welke categorie je valt, schrijf ons dan vóór het sluiten van de overeenkomst. Bij uitlegverschil, en wanneer er aanwijzingen voor beide hoedanigheden zijn, geldt het consumentenregime als het meest beschermende."]}, {"h": "Wat het platform is en wat niet", "p": ["NX036 is een technologieplatform dat toegang geeft tot een catalogus van producten van leveranciers, bestellingen beheert en de verzending en inklaring ervan coördineert.", "Wordt de bestelling geplaatst door een consument in onze eigen winkel, dan treden wij op als verkoper en zijn wij als zodanig jegens hem aansprakelijk, met alles wat daarbij hoort.", "Gebruikt een wederverkoper het platform om bestellingen van ZIJN klanten uit te voeren, dan is de verkoop aan die eindklanten de zijne, niet de onze: wij verkopen aan hem en verlenen hem de logistieke dienst. Hij is degene die met zijn koper contracteert, zijn factuur uitreikt, de nazorg verzorgt en instaat voor de wettelijke verplichtingen van die verkoop.", "Wij vervaardigen de producten niet. Waar de regelgeving dat vereist treden wij op als marktdeelnemer in de Unie, en die informatie staat op de pagina van elk product en op de factuur."]}, {"h": "Je account", "p": ["Om het platform te gebruiken heb je een account nodig, moet je meerderjarig zijn en bekwaam om overeenkomsten te sluiten. De gegevens die je ons verstrekt moeten juist en actueel zijn; zijn ze dat niet meer, werk ze dan bij.", "Je bent verantwoordelijk voor de vertrouwelijkheid van je inloggegevens en voor de activiteit die met je account plaatsvindt. Vermoed je onbevoegde toegang, laat het ons dan meteen weten en wijzig je wachtwoord. We bieden verificatie in twee stappen en raden aan die in te schakelen.", "Een account is persoonlijk en niet overdraagbaar. Je mag het niet overdragen, doorverkopen of de toegang delen met derden buiten je organisatie."]}, {"h": "Prijzen, betalingen en belastingen", "p": ["Prijzen worden getoond in de valuta die je actief hebt, met belastingen en verzendkosten gespecificeerd vóór bevestiging. Het in rekening gebrachte bedrag is het bedrag uit dat overzicht.", "Betalingen worden verwerkt via gespecialiseerde aanbieders (Stripe, PayPal) of met het saldo van je portemonnee. We bewaren geen volledige kaartgegevens.", "Prijzen kunnen op elk moment wijzigen, maar nooit met terugwerkende kracht: een reeds bevestigde bestelling behoudt de prijs waartegen zij is bevestigd. Abonnementen verlengen volgens de afgesloten periode totdat je ze opzegt.", "Invoerrechten en -belastingen die voor de bestemming gelden worden vóór betaling berekend en getoond. Vraagt de bestemming aanvullende formaliteiten van de ontvanger, dan melden we dat."]}, {"h": "Bestellingen, verzending en douane", "p": ["Een bestelling komt tot stand wanneer wij haar bevestigen, niet eerder. We kunnen een bestelling weigeren of annuleren —met volledige terugbetaling van het in rekening gebrachte— als het product niet meer beschikbaar is, bij een kennelijke prijsfout, als de bestemming niet bediend kan worden of als we frauduleus gebruik vaststellen.", "De getoonde levertijden zijn schattingen op basis van informatie van de vervoerder, geen harde datumtoezeggingen, tenzij uitdrukkelijk anders vermeld.", "Internationale zendingen zijn onderworpen aan de douanecontroles van het land van bestemming. Opdat het pakket aankomt, ontvangen de vervoerder en de autoriteiten de gegevens van de ontvanger en van de goederen, zoals uiteengezet in het privacybeleid.", "Sommige producten kunnen wegens wettelijke of vervoerdersbeperkingen niet naar bepaalde bestemmingen worden verzonden. Het platform staat het afronden van zulke bestellingen niet toe."]}, {"h": "Ben je consument: je rechten", "p": ["Je hebt het recht de overeenkomst te herroepen binnen VEERTIEN (14) kalenderdagen na ontvangst van het product, zonder opgave van redenen en zonder boete. Je kunt ons dat op elke ondubbelzinnige wijze laten weten, ook per e-mail aan support@nx036.com. De details en de wettelijke uitzonderingen staan in ons herroepingsbeleid.", "Op de producten rust de wettelijke conformiteitsgarantie van DRIE (3) jaar vanaf levering, naar Spaans recht. Is het product niet conform, dan heb je recht op herstel of vervanging en, waar van toepassing, op prijsvermindering of ontbinding van de overeenkomst. De eerste twee jaar wordt vermoed dat het gebrek al bij levering bestond, dus dat hoef je niet te bewijzen.", "Geen enkele clausule van deze voorwaarden beperkt, sluit uit of stelt voorwaarden aan die rechten. Zou er een in die zin kunnen worden uitgelegd, dan geldt zij ten aanzien van jou als niet geschreven.", "Is iets niet naar tevredenheid opgelost, dan kun je terecht bij een erkende instantie voor alternatieve geschillenbeslechting (ADR), bij het netwerk van Europese Consumenten Centra (ECC-Net) als je vanuit een ander EU-land koopt, of bij de consumentenautoriteiten van je land van verblijf."]}, {"h": "Ben je onderneming of wederverkoper: je verplichtingen", "p": ["Verkoop je door aan je eigen klanten, dan ben JIJ jegens hen de verkoper. Het is aan jou hen te informeren volgens het toepasselijke recht, de factuur uit te reiken, hun herroeping en wettelijke garantie af te handelen en de fiscale verplichtingen van die verkoop na te komen.", "Je verbindt je ertoe de producten naar waarheid te beschrijven en er geen eigenschappen, certificeringen of herkomsten aan toe te schrijven die ze niet hebben, en in je verkoopmateriaal merk- en intellectuele-eigendomsrechten van derden te respecteren.", "VRIJWARING. Je vrijwaart ons —ons, ons personeel en onze leveranciers— tegen elke aanspraak, sanctie, schade of kosten, met inbegrip van redelijke kosten van juridische verdediging, die voortvloeien uit jouw schending van deze voorwaarden, van de op jouw activiteit toepasselijke regelgeving, of uit de verhouding tussen jou en je eindklanten. Deze verplichting blijft na het einde van de overeenkomst bestaan.", "Integreer je het platform via onze API of onze koppelingen, dan houd je je aan de gepubliceerde gebruikslimieten en gebruik je het niet om de catalogus te repliceren voor doeleinden buiten de afgesproken wederverkoop."]}, {"h": "Wat gebeurt er als er iets misgaat", "p": ["Komt de bestelling niet aan, beschadigd aan, onvolledig aan of komt zij niet overeen met wat is besteld, meld het ons dan via je account of per e-mail aan support@nx036.com, met vermelding van het bestelnummer. Hoe eerder we het weten, hoe eerder we kunnen reclameren bij de vervoerder, die eigen termijnen hanteert.", "We openen een melding en houden je op de hoogte van het verloop. Afhankelijk van het geval is de oplossing herzending van het product, vervanging of terugbetaling van wat je hebt betaald; ligt de verantwoordelijkheid bij de vervoerder, dan handelen wij de claim met hem af.", "Terugbetalingen gebeuren op hetzelfde betaalmiddel dat je hebt gebruikt, tenzij anders afgesproken. De termijn hangt na het geven van de opdracht af van jouw bank, niet van ons.", "Is het probleem een storing van de dienst of een fout van het platform, meld het dan net zo goed: ook technische incidenten worden geregistreerd en beantwoord."]}, {"h": "Onze aansprakelijkheid", "p": ["Wij staan in voor de correcte nakoming van de verplichtingen die wij in deze voorwaarden op ons nemen, overeenkomstig het toepasselijke recht.", "NIETS IN DEZE OVEREENKOMST SLUIT ONZE AANSPRAKELIJKHEID UIT OF BEPERKT HAAR bij opzet, grove schuld, persoonlijk letsel, productaansprakelijkheid, of enige andere die de wet niet toestaat uit te sluiten. Elke beperking in deze sectie geldt onder dat voorbehoud.", "Jegens KLANTEN DIE GEEN CONSUMENT ZIJN en voor zover de wet dat toestaat: wij zijn niet aansprakelijk voor winstderving, verlies van omzet, van klanten, van gegevens of van kansen, noch voor indirecte of gevolgschade; en onze totale aansprakelijkheid voor welke aanspraak dan ook is beperkt tot het bedrag dat je ons in de twaalf maanden vóór de gebeurtenis hebt betaald.", "Wij zijn niet aansprakelijk voor jouw gebruik van het platform in strijd met deze voorwaarden of met de wet, noch voor de verplichtingen die op jou rusten jegens je eigen klanten."]}, {"h": "Beschikbaarheid van de dienst", "p": ["We werken eraan dat het platform doorlopend beschikbaar is, maar we garanderen geen ononderbroken of foutloze beschikbaarheid. Er kan uitval zijn door onderhoud, updates of oorzaken buiten ons bereik.", "Is onderhoud gepland en zal het de dienst raken, dan proberen we redelijk op voorhand te waarschuwen en het uit te voeren tijdens rustige uren.", "We kunnen functionaliteiten wijzigen, opschorten of intrekken. Benadeelt een wijziging je wezenlijk en heb je een lopend abonnement, dan kun je dat opzeggen met terugbetaling van het niet gebruikte deel."]}, {"h": "Aanvaardbaar gebruik en opschorting", "p": ["Je mag het platform niet gebruiken voor onrechtmatige doeleinden, om rechten van derden te schenden, om schadelijke code te introduceren, om te proberen toegang te krijgen tot andermans gegevens of accounts, noch voor reverse engineering, massale gegevensextractie of enig gebruik dat de dienst aantast.", "We kunnen een account opschorten of sluiten dat deze voorwaarden of de wet schendt, of bij gegronde verdenking van fraude. Tenzij spoed of de wet zich ertegen verzet, waarschuwen we je vooraf met opgave van de reden, en kun je aanvoeren wat je gepast acht.", "Opschorting ontslaat je niet van reeds verschuldigde bedragen en raakt lopende bestellingen niet, die naargelang het geval worden voltooid of terugbetaald."]}, {"h": "Intellectuele eigendom", "p": ["Het platform, de software, het ontwerp, de merken en de content die wij maken zijn van ons of van wie ons het gebruik ervan in licentie heeft gegeven. Je account geeft je het recht de dienst te gebruiken, niet om je een van die elementen toe te eigenen.", "Afbeeldingen en beschrijvingen uit de catalogus worden je ter beschikking gesteld om de via het platform verworven producten te verkopen. Dat gebruik maakt je geen rechthebbende erop en geeft je geen toestemming ze voor andere doeleinden te gebruiken.", "Content die jij aanlevert blijft van jou; door die te publiceren verleen je ons de licentie die strikt nodig is om je de dienst te leveren."]}, {"h": "Overmacht", "p": ["Wij zijn niet aansprakelijk voor niet-nakoming of vertraging als gevolg van omstandigheden buiten onze redelijke macht: natuurrampen, gewapende conflicten, onlusten, epidemieën, stakingen buiten ons eigen personeel, besluiten van autoriteiten, sluiting van grenzen of douane, grootschalige storingen van telecommunicatienetwerken of van de stroomvoorziening.", "Duurt de omstandigheid langer dan dertig dagen, dan kan elk van beide partijen de betrokken overeenkomst ontbinden, met terugbetaling van wat is betaald en niet geleverd. Deze bepaling dekt geen enkele economische tegenslag of kostenstijging."]}, {"h": "Duur, opzegging en beëindiging", "p": ["De overeenkomst geldt zolang je je account behoudt. Je kunt het sluiten wanneer je wilt via je profiel, zonder opgave van redenen en zonder boete.", "Sluiting zegt op zichzelf geen lopend abonnement op en raakt reeds bevestigde bestellingen niet. Fiscale documentatie bewaren we zolang de wet dat vereist, zoals uiteengezet in het privacybeleid.", "Bepalingen die naar hun aard het einde moeten overleven —vrijwaring, aansprakelijkheid, intellectuele eigendom, toepasselijk recht en bevoegde rechter— blijven van kracht."]}, {"h": "Wijzigingen in deze voorwaarden", "p": ["We kunnen deze voorwaarden wijzigen om ze aan te passen aan juridische, technische of dienstgerelateerde veranderingen. We publiceren de nieuwe versie met haar datum en waarschuwen alle actieve accounts per e-mail.", "Ben je het niet eens met de nieuwe versie, dan kun je je account sluiten voordat die van kracht wordt. Eerder bevestigde bestellingen vallen onder de versie die gold op het moment van bevestiging."]}, {"h": "Gedeeltelijke nietigheid", "p": ["Verklaart een bevoegde autoriteit een bepaling nietig of niet-afdwingbaar, dan wordt die bepaling voor zover de wet dat toestaat vervangen door een geldige met gelijkwaardig effect, en blijft de rest van de overeenkomst volledig van kracht."]}, {"h": "Toepasselijk recht en geschillenbeslechting", "p": ["Deze voorwaarden worden beheerst door het recht van het land waar wij gevestigd zijn, onverminderd dwingende regels die van toepassing kunnen zijn.", "Ben je CONSUMENT, dan ontneemt deze keuze je niet de bescherming van de dwingende regels van je land van gewone verblijfplaats, en kun je procederen en gedagvaard worden voor de rechter van je woonplaats.", "Ben je GEEN consument, dan onderwerpen partijen zich aan de rechtbanken van onze vestigingsplaats, met afstand van elk ander forum dat hun zou toekomen.", "Voordat je naar de rechter stapt, vragen we je ons te schrijven op support@nx036.com: de meeste problemen worden zo opgelost, en sneller."]}]}','2026-08-15'),
('cookies','es','Política de cookies','{"intro": "Usamos las cookies imprescindibles para que la web funcione y recuerde tus preferencias. Hoy NO cargamos cookies de analítica ni de publicidad: si algún día lo hacemos, no se activarán hasta que las aceptes y aparecerán en la tabla de abajo.", "sections": [{"h": "¿Qué son?", "p": ["Pequeños archivos que se guardan en tu dispositivo para recordar información entre visitas: que has iniciado sesión, en qué idioma navegas o qué moneda prefieres."]}, {"h": "Cuáles usamos exactamente", "p": ["El detalle está en la tabla que acompaña a esta página: nombre, quién la pone, para qué sirve y cuánto dura. Todas las que usamos hoy son necesarias para el funcionamiento y por eso no requieren tu consentimiento."]}, {"h": "Analítica y marketing", "p": ["Las categorías existen en el panel de preferencias, pero ahora mismo no hay ningún proveedor de analítica ni de publicidad cargado en la web. Si lo incorporamos, actualizaremos esta página y la cookie no se activará hasta que la aceptes."]}, {"h": "Cómo cambiar de opinión", "p": ["Desde el enlace «Preferencias de cookies» del pie de página puedes volver a abrir el panel y aceptar, rechazar o ajustar por categoría cuando quieras. Retirar el consentimiento es tan fácil como darlo. También puedes borrar las cookies desde tu navegador."]}, {"h": "Si no aceptas", "p": ["La web sigue funcionando con normalidad: puedes navegar, comprar y gestionar tu cuenta. Las cookies necesarias no se pueden desactivar porque sin ellas no hay sesión ni seguridad."]}]}','2026-08-15'),
('cookies','en','Cookie policy','{"intro": "We use the cookies strictly needed for the site to work and remember your preferences. Today we load NO analytics or advertising cookies: if we ever do, they will not run until you accept them and they will appear in the table below.", "sections": [{"h": "What they are", "p": ["Small files stored on your device to remember information between visits: that you are signed in, what language you browse in, or which currency you prefer."]}, {"h": "Exactly which ones we use", "p": ["The detail is in the table on this page: name, who sets it, what it does and how long it lasts. Everything we use today is necessary for the site to work, which is why it does not require your consent."]}, {"h": "Analytics and marketing", "p": ["The categories exist in the preferences panel, but right now there is no analytics or advertising provider loaded on the site. If we add one, we will update this page and the cookie will not run until you accept it."]}, {"h": "Changing your mind", "p": ["The “Cookie preferences” link in the footer reopens the panel so you can accept, reject or adjust by category whenever you want. Withdrawing consent is as easy as giving it. You can also delete cookies from your browser."]}, {"h": "If you do not accept", "p": ["The site keeps working normally: you can browse, buy and manage your account. Necessary cookies cannot be switched off because without them there is no session and no security."]}]}','2026-08-15'),
('notice','es','Aviso legal','{"intro": "Información sobre quién presta este servicio, exigida por la normativa de comercio electrónico de la Unión Europea (Directiva 2000/31/CE y su transposición española, la LSSI-CE) y por el artículo 13 del RGPD.", "sections": [{"h": "Titular del sitio", "p": ["Titular: Jesús Enrique Finol Finol", "Forma jurídica: empresario individual (persona física)", "Nombre comercial: NX036", "NIF: PENDIENTE-NIF", "Domicilio: Calle Castelví 7, 1D, 50004 Zaragoza, España", "Correo electrónico de contacto: support@nx036.com"]}, {"h": "Objeto", "p": ["Este sitio permite comprar los productos publicados en el catálogo y, a los usuarios registrados como vendedores, importar productos y gestionar sus pedidos. El uso del sitio implica la aceptación de los términos de servicio."]}, {"h": "Propiedad intelectual", "p": ["Los textos, el diseño y el software del sitio pertenecen a su titular o se usan con autorización. Las imágenes y descripciones de los productos proceden de los catálogos de los proveedores y pertenecen a sus respectivos titulares."]}, {"h": "Responsabilidad", "p": ["Nos esforzamos por que la información del catálogo sea exacta y esté al día, pero procede en buena parte de terceros. Si detectas un error en una ficha, un precio o una imagen, escríbenos y lo corregimos."]}, {"h": "Reclamaciones", "p": ["Puedes dirigir cualquier reclamación a support@nx036.com. Te responderemos por escrito. Como consumidor, conservas además el derecho de acudir a las autoridades de consumo de tu país de residencia, y puedes usar la red de Centros Europeos del Consumidor (ECC-Net) para reclamaciones transfronterizas dentro de la UE."]}, {"h": "Ley aplicable", "p": ["Estas condiciones se rigen por la legislación española, por ser España el país donde el titular tiene su domicilio. Ahora bien: si compras como consumidor, esto NO te quita ni un ápice de la protección que te dan las normas imperativas del país donde resides. Como dirigimos nuestra actividad a tu mercado, el Reglamento (CE) 593/2008 (Roma I, art. 6) mantiene aplicables esas normas, y puedes demandarnos ante los tribunales de tu propio domicilio."]}]}','2026-08-15'),
('notice','en','Legal notice','{"intro": "Information about who provides this service, as required by EU electronic-commerce rules (Directive 2000/31/EC as implemented in Ireland) and by article 13 of the GDPR.", "sections": [{"h": "Site owner", "p": ["Owner: Jesús Enrique Finol Finol", "Legal form: sole trader (natural person)", "Trading name: NX036", "Tax ID: PENDIENTE-NIF", "Address: Calle Castelví 7, 1D, 50004 Zaragoza, España", "Contact email: support@nx036.com"]}, {"h": "Purpose", "p": ["This site lets you buy the products listed in the catalogue and, for users registered as sellers, import products and manage their orders. Using the site implies acceptance of the terms of service."]}, {"h": "Intellectual property", "p": ["The texts, design and software of the site belong to its owner or are used with permission. Product images and descriptions come from suppliers’ catalogues and belong to their respective owners."]}, {"h": "Liability", "p": ["We work to keep catalogue information accurate and current, but much of it comes from third parties. If you spot an error in a listing, a price or an image, write to us and we will fix it."]}, {"h": "Complaints", "p": ["You may send any complaint to support@nx036.com. We will reply in writing. As a consumer you also keep the right to turn to the consumer authorities of your country of residence, and you can use the European Consumer Centres Network (ECC-Net) for cross-border complaints within the EU."]}, {"h": "Applicable law", "p": ["These terms are governed by Spanish law, as Spain is where the owner is domiciled. That said: if you buy as a consumer, this takes nothing away from the protection given to you by the mandatory rules of your country of residence. Because we direct our activity at your market, Regulation (EC) 593/2008 (Rome I, art. 6) keeps those rules applicable, and you may sue us in the courts of your own domicile."]}]}','2026-08-15'),
('withdrawal','es','Derecho de desistimiento y devoluciones','{"intro": "Si compras como consumidor, tienes 14 días naturales para arrepentirte sin dar ninguna explicación. Aquí está cómo, hasta cuándo y qué pasa con tu dinero.", "sections": [{"h": "Cuánto tiempo tienes", "p": ["Catorce días naturales desde que tú o alguien que designes recibe el último producto del pedido. Es el plazo que garantiza la Directiva 2011/83/UE en toda la Unión Europea; si la norma de tu país es más favorable, se aplica la tuya. Si el pedido llega en varios envíos, el plazo cuenta desde el último. No tienes que justificar tu decisión ni pagar penalización alguna."]}, {"h": "Cómo desistir", "p": ["Basta con que nos comuniques tu decisión de forma inequívoca antes de que venza el plazo: escríbenos a support@nx036.com indicando tu número de pedido, o usa el formulario que encontrarás más abajo. También puedes hacerlo desde el detalle del pedido en tu cuenta.", "Para cumplir el plazo basta con que envíes la comunicación ANTES de que venza. No hace falta que el producto haya llegado ya de vuelta."]}, {"h": "Devolver el producto", "p": ["Tendrás que devolvernos el producto sin demora indebida y, en todo caso, en los 14 días naturales siguientes a comunicarnos tu decisión. Los costes directos de la devolución corren de tu cuenta; dado que los envíos salen de Asia, te diremos la dirección y el importe estimado en cuanto nos avises, para que decidas con la cifra delante."]}, {"h": "Cuándo recuperas tu dinero", "p": ["Te devolveremos todos los pagos recibidos, incluidos los gastos de envío estándar, sin demora indebida y a más tardar 14 días naturales desde que nos comunicas el desistimiento. Podemos retener el reembolso hasta haber recibido el producto o hasta que nos pruebes que lo has enviado, lo que ocurra primero. El reembolso se hace por el mismo medio de pago que usaste, sin coste adicional."]}, {"h": "Cuándo NO se aplica", "p": ["La ley excluye algunos casos: productos hechos a medida o claramente personalizados, los que puedan deteriorarse rápidamente, y los precintados que no puedan devolverse por razones de higiene o salud si fueron desprecintados tras la entrega. Si un producto de tu pedido está en alguno de estos supuestos, te lo indicamos en su ficha antes de comprar."]}, {"h": "Si el producto llega defectuoso", "p": ["Eso no es desistimiento sino falta de conformidad, y tienes garantía legal desde la entrega: como mínimo dos años en toda la UE (Directiva 2019/771), y más si tu país lo amplía — en España son tres. Escríbenos y lo resolvemos: reparación, sustitución, rebaja del precio o resolución del contrato. No te cuesta nada y no consume tu plazo de desistimiento."]}, {"h": "Formulario de desistimiento", "p": ["Puedes copiar este texto y enviárnoslo por correo electrónico. No es obligatorio usarlo, pero facilita las cosas.", "A la atención de Jesús Enrique Finol Finol, Calle Castelví 7, 1D, 50004 Zaragoza, España, support@nx036.com:", "Por la presente le comunico que desisto de mi contrato de venta del siguiente bien: ______________________. Pedido número: ______________. Recibido el: ____/____/______. Nombre del consumidor: ______________________. Domicilio del consumidor: ______________________. Fecha: ____/____/______."]}]}','2026-08-15'),
('withdrawal','en','Right of withdrawal and returns','{"intro": "If you buy as a consumer, you have 14 calendar days to change your mind without giving any reason. Here is how, until when, and what happens to your money.", "sections": [{"h": "How long you have", "p": ["Fourteen calendar days from the day you, or someone you designate, receives the last item of the order. That is the period Directive 2011/83/EU guarantees across the European Union; if your country’s rules are more favourable, yours apply. If the order arrives in several shipments, the period runs from the last one. You do not have to justify your decision or pay any penalty."]}, {"h": "How to withdraw", "p": ["Just tell us your decision unambiguously before the deadline: write to support@nx036.com quoting your order number, or use the form below. You can also do it from the order detail in your account.", "To meet the deadline it is enough that you send the communication BEFORE it expires. The product does not need to have arrived back yet."]}, {"h": "Returning the product", "p": ["You must send the product back without undue delay and in any case within 14 calendar days of telling us your decision. The direct cost of returning it is yours; since shipments leave from Asia, we will give you the address and the estimated cost as soon as you tell us, so you can decide with the figure in front of you."]}, {"h": "When you get your money back", "p": ["We will refund all payments received, including standard delivery costs, without undue delay and at the latest 14 calendar days after you tell us. We may withhold the refund until we receive the product or until you prove you have sent it, whichever comes first. Refunds go back to the same payment method you used, at no extra cost."]}, {"h": "When it does NOT apply", "p": ["The law excludes some cases: custom-made or clearly personalised goods, those liable to deteriorate rapidly, and sealed goods that cannot be returned for health or hygiene reasons once unsealed after delivery. If an item in your order falls under any of these, we say so on its page before you buy."]}, {"h": "If the product arrives faulty", "p": ["That is not withdrawal but lack of conformity, and you have a legal guarantee from delivery: at least two years across the EU (Directive 2019/771), and longer where your country extends it — three years in Spain, for example. Write to us and we will sort it: repair, replacement, price reduction or termination. It costs you nothing and does not use up your withdrawal period."]}, {"h": "Withdrawal form", "p": ["You can copy this text and email it to us. Using it is not compulsory, but it makes things easier.", "To Jesús Enrique Finol Finol, Calle Castelví 7, 1D, 50004 Zaragoza, España, support@nx036.com:", "I hereby give notice that I withdraw from my contract of sale of the following goods: ______________________. Order number: ______________. Received on: ____/____/______. Consumer name: ______________________. Consumer address: ______________________. Date: ____/____/______."]}]}','2026-08-15')
ON CONFLICT (doc_type, lang) DO NOTHING;
